let LANG=localStorage.getItem('qalab-lang')||'pt';let DATA={},UI={};let topicMeta={};
const QA_BASE_URL='https://qualityassurancebrasil.com.br';
function qaRouteKey(){return decodeURIComponent(location.pathname.replace(/^\/+|\/+$/g,''));}
function qaNavigate(key){const path=key?'/'+encodeURIComponent(key):'/';if(location.pathname!==path)history.pushState({},'',path);route();}
function qaUpdateSeo(key){
 const canonical=QA_BASE_URL+(key?'/'+encodeURIComponent(key):'/');
 const d=key&&DATA[key]?DATA[key][LANG]:null;
 const title=d?`${d.title} | QA Lab Brasil`:'QA Lab Brasil | Quality Assurance e Testes de Software';
 const desc=d?(d.subtitle||'Conteúdo prático de Quality Assurance e Quality Engineering no QA Lab Brasil.'):'Aprenda Quality Assurance, testes de software, automação, APIs, Playwright, Selenium, Jira, Xray e boas práticas de QA no QA Lab Brasil.';
 document.title=title;
 const set=(sel,attr,val)=>{const e=document.querySelector(sel);if(e)e.setAttribute(attr,val)};
 set('meta[name="description"]','content',desc);set('link[rel="canonical"]','href',canonical);
 set('meta[property="og:title"]','content',title);set('meta[property="og:description"]','content',desc);set('meta[property="og:url"]','content',canonical);
 set('meta[name="twitter:title"]','content',title);set('meta[name="twitter:description"]','content',desc);
}

async function load(){try{const [topicsRes,uiRes]=await Promise.all([fetch('/content/topics.json?v=2.6-seo',{cache:'no-store'}),fetch('/data/ui.json?v=2.6-seo',{cache:'no-store'})]);if(!topicsRes.ok)throw new Error('topics.json HTTP '+topicsRes.status);if(!uiRes.ok)throw new Error('ui.json HTTP '+uiRes.status);DATA=await topicsRes.json();UI=await uiRes.json();Object.entries(DATA).forEach(([k,v])=>topicMeta[k]=[v._meta.icon,v._meta.color,v._meta.group,v._meta.official]);bind();route();}catch(err){console.error('QA Lab bootstrap failed:',err);const main=document.getElementById('main');if(main)main.innerHTML='<section class="section"><h2>Falha ao carregar o QA Lab</h2><p>Atualize a página. Se o problema continuar, verifique o console do navegador.</p></section>';}}
function t(k){return UI[LANG]?.[k]||UI.pt[k]||k}
function bind(){organizeNavigation();document.querySelectorAll('.group-toggle').forEach(b=>b.onclick=()=>{let g=b.closest('.nav-group');g.classList.toggle('open');b.querySelector('.plus').textContent=g.classList.contains('open')?'−':'+'});document.querySelectorAll('.lang').forEach(b=>b.onclick=()=>{const _sq=document.getElementById('searchInput');if(_sq)_sq.value='';document.getElementById('searchResults')?.classList.remove('open');LANG=b.dataset.lang;localStorage.setItem('qalab-lang',LANG);document.documentElement.lang=LANG==='pt'?'pt-BR':LANG;document.querySelectorAll('.lang').forEach(x=>x.classList.toggle('on',x.dataset.lang===LANG));updateLanguagePicker();document.querySelector('.language-picker')?.classList.remove('open');route();});document.querySelectorAll('.lang').forEach(x=>x.classList.toggle('on',x.dataset.lang===LANG));document.getElementById('languagePickerBtn')?.addEventListener('click',e=>{e.stopPropagation();document.querySelector('.language-picker')?.classList.toggle('open')});document.addEventListener('click',()=>document.querySelector('.language-picker')?.classList.remove('open'));updateLanguagePicker();const q=document.getElementById('searchInput');q.addEventListener('input',()=>search(q.value));const sa=document.getElementById('searchAction');if(sa)sa.onclick=()=>{qaLabOpenBestSearchResult()};const bt=document.getElementById('backToTop');if(bt)bt.onclick=()=>qaBackToTopAll();document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();q.focus();search(q.value)}});document.getElementById('chatFab').onclick=()=>document.getElementById('chatbox').classList.toggle('open');document.querySelector('.chat-input button').onclick=askAssistant;document.getElementById('chatInput').addEventListener('keydown',e=>{if(e.key==='Enter')askAssistant()});window.addEventListener('popstate',route);}
function navLabels(){qaUpdateSeo(qaRouteKey());let tdb=document.getElementById('testDataHeaderBtn');if(tdb)tdb.innerHTML='🧪 <span>'+({pt:'Gerar Massa',en:'Test Data',es:'Generar Datos'}[LANG])+'</span>';let smb=document.getElementById('simulatorHeaderBtn');if(smb)smb.innerHTML='🎓 <span>'+({pt:'Simulados',en:'Practice Exams',es:'Simuladores'}[LANG])+'</span>';document.getElementById('searchInput').placeholder=t('search');document.querySelector('[data-ui=home] span').textContent=t('home');organizeNavigation();document.getElementById('chatMsg').textContent=LANG==='en'?'Ask about QA Lab content. The assistant searches the knowledge base available on the site.':LANG==='es'?'Pregunte sobre el contenido de QA Lab. El asistente busca en la base de conocimiento disponible en el sitio.':'Pergunte sobre o conteúdo do QA Lab. O assistente pesquisa a base de conhecimento disponível no site.';document.getElementById('chatInput').placeholder=LANG==='en'?'Ex.: What is the difference between 401 and 403?':LANG==='es'?'Ej.: ¿Cuál es la diferencia entre 401 y 403?':'Ex.: Qual a diferença entre 401 e 403?';}
function qaTrackPageView(){if(location.hostname!=='qualityassurancebrasil.com.br'&&location.hostname!=='www.qualityassurancebrasil.com.br')return;if(typeof gtag!=='function')return;const pageTitle=document.querySelector('#main h1')?.textContent?.trim()||document.title;gtag('config','G-F1SV6ME5JX',{send_page_view:true,page_title:pageTitle,page_location:location.href});}function route(){navLabels();let h=qaRouteKey();qaUpdateSeo(h);if(h==='toolkit')renderToolkit();else if(h==='glossary')renderGlossary();else if(h==='how-to-test')renderHowToTest();else if(h==='api-lab')renderApiLab();else if(h==='bug-clinic')renderBugClinic();else if(h==='qa-shop')renderQaShop();else if(h==='simulators')renderSimulators();else if(h==='test-data-generator')renderTestDataGenerator();else if(h&&DATA[h])renderTopic(h);else renderHome();window.setTimeout(qaTrackPageView,0);}
function renderHome(){let m=document.getElementById('main');let heroSlides={
pt:[
 ['Aprenda','Construa uma base sólida em Quality Assurance e Engenharia de Qualidade, dos fundamentos aos conceitos que sustentam testes, automação e estratégia.'],
 ['Consulte','Encontre rapidamente conceitos, ferramentas, técnicas, guias e referências para apoiar decisões e dúvidas do dia a dia de QA.'],
 ['Pratique','Transforme conhecimento em experiência com laboratórios, exemplos, checklists, exercícios e recursos práticos para diferentes cenários de qualidade.'],
 ['Aplique','Leve o conhecimento para projetos reais com automação, APIs, dados, DevOps, IA, arquitetura, métricas e liderança de qualidade.']],
en:[
 ['Learn','Build a solid foundation in Quality Assurance and Quality Engineering, from core concepts to the principles behind testing, automation and strategy.'],
 ['Consult','Quickly find concepts, tools, techniques, guides and references to support everyday QA questions and decisions.'],
 ['Practice','Turn knowledge into experience with labs, examples, checklists, exercises and practical resources for different quality scenarios.'],
 ['Apply','Bring knowledge into real projects with automation, APIs, data, DevOps, AI, architecture, metrics and quality leadership.']],
es:[
 ['Aprenda','Construya una base sólida en Quality Assurance e Ingeniería de Calidad, desde los fundamentos hasta los conceptos que sustentan pruebas, automatización y estrategia.'],
 ['Consulte','Encuentre rápidamente conceptos, herramientas, técnicas, guías y referencias para apoyar decisiones y dudas del día a día de QA.'],
 ['Practique','Transforme conocimiento en experiencia con laboratorios, ejemplos, checklists, ejercicios y recursos prácticos para diferentes escenarios de calidad.'],
 ['Aplique','Lleve el conocimiento a proyectos reales con automatización, APIs, datos, DevOps, IA, arquitectura, métricas y liderazgo de calidad.']]}[LANG];
let eyebrow={pt:'🧪 PLATAFORMA DE CONHECIMENTO EM ENGENHARIA DE QUALIDADE',en:'🧪 QUALITY ENGINEERING KNOWLEDGE PLATFORM',es:'🧪 PLATAFORMA DE CONOCIMIENTO EN INGENIERÍA DE CALIDAD'}[LANG];let cards=Object.entries(DATA).map(([k,v])=>{let d=v[LANG],meta=topicMeta[k];let more=LANG==='en'?'Learn more':LANG==='es'?'Saber más':'Saiba mais';let go=LANG==='en'?'Go to content':LANG==='es'?'Ir al contenido':'Ir para o conteúdo';return `<article class="card explore-card" style="--accent:${meta[1]}"><div class="ico">${meta[0]}</div><b>${d.title}</b><p>${d.subtitle}</p><span class="tag">${t('level1')} → ${t('level3')}</span><button class="learn-more-btn" type="button" onclick="event.stopPropagation();toggleHomeMore(this)">${more} <span class="more-arrow">→</span></button><div class="home-more"><p>${d.sections?.[0]?.[1]||d.subtitle}</p><button class="btn" onclick="qaNavigate('${k}')">${go} →</button></div></article>`}).join('');let exploreSub=LANG==='en'?'Explore content, tools, guides and practical resources for Quality Assurance and Quality Engineering.':LANG==='es'?'Explore contenidos, herramientas, guías y recursos prácticos para Quality Assurance y Quality Engineering.':'Explore conteúdos, ferramentas, guias e recursos práticos para Quality Assurance e Quality Engineering.';m.innerHTML=`<section class="hero"><div class="hero-copy" id="heroCopy"><span class="eyebrow">${eyebrow}</span><h1 id="heroTitle">${heroSlides[0][0]}</h1><p id="heroDesc">${heroSlides[0][1]}</p></div><div class="hero-nav"><button class="hero-arrow" type="button" onclick="changeHero(-1)" aria-label="${LANG==='en'?'Previous message':LANG==='es'?'Mensaje anterior':'Mensagem anterior'}">‹</button><div class="hero-dots">${heroSlides.map((_,i)=>`<button class="hero-dot ${i===0?'on':''}" type="button" onclick="setHero(${i})" aria-label="${i+1}"></button>`).join('')}</div><button class="hero-arrow" type="button" onclick="changeHero(1)" aria-label="${LANG==='en'?'Next message':LANG==='es'?'Mensaje siguiente':'Próxima mensagem'}">›</button></div><div class="actions"><button class="btn primary" onclick="qaNavigate('qa')">🧭 ${LANG==='en'?'Start in QA':LANG==='es'?'Comenzar en QA':'Começar em QA'}</button><button class="btn" onclick="qaNavigate('testing')">🧪 ${LANG==='en'?'Study testing':LANG==='es'?'Estudiar pruebas':'Estudar testes'}</button><button class="btn" onclick="qaNavigate('api')">🔌 API</button><button class="btn" onclick="qaNavigate('ai')">🧠 IA</button></div><div class="stats"><div class="stat"><strong>${Object.keys(DATA).length}</strong><span>${LANG==='en'?'implemented modules':LANG==='es'?'módulos implementados':'módulos implementados'}</span></div><div class="stat"><strong>PT · EN · ES</strong><span>${LANG==='en'?'3 languages':LANG==='es'?'3 idiomas':'3 idiomas'}</span></div><div class="stat"><strong>🟢 🔵 🟣</strong><span>${t('level1')} → ${t('level3')}</span></div><button class="stat pdf-hub-stat" type="button" onclick="qaOpenPdfHub()"><strong>${LANG==='en'?'📄 PDF Center':LANG==='es'?'📄 Central de PDFs':'📄 Central de PDFs'}</strong><span class="pdf-hub-cta">${LANG==='en'?'Explore materials →':LANG==='es'?'Explorar materiales →':'Explorar materiais →'}</span></button></div></section><section class="section"><div class="section-head"><div><h2>${t('explore')}</h2><p>${exploreSub}</p></div></div><div class="grid">${cards}</div></section>${aboutContact()}`;window._heroSlides=heroSlides;window._heroIndex=0;initHeroGestures();}
function initHeroGestures(){let hero=document.querySelector('.hero');if(!hero)return;let startX=0,startY=0,dragging=false,pointerId=null;const interactive='button,a,input,select,textarea';hero.addEventListener('pointerdown',e=>{if(e.target.closest(interactive))return;startX=e.clientX;startY=e.clientY;dragging=true;pointerId=e.pointerId;hero.classList.add('is-dragging');try{hero.setPointerCapture(pointerId)}catch(_){}});hero.addEventListener('pointerup',e=>{if(!dragging)return;let dx=e.clientX-startX,dy=e.clientY-startY;dragging=false;hero.classList.remove('is-dragging');try{hero.releasePointerCapture(pointerId)}catch(_){}if(Math.abs(dx)>=55&&Math.abs(dx)>Math.abs(dy)*1.2)changeHero(dx<0?1:-1)});hero.addEventListener('pointercancel',()=>{dragging=false;hero.classList.remove('is-dragging')});}
function setHero(i){let slides=window._heroSlides;if(!slides?.length)return;window._heroIndex=(i+slides.length)%slides.length;let copy=document.getElementById('heroCopy');if(copy)copy.classList.add('is-changing');setTimeout(()=>{let s=slides[window._heroIndex],title=document.getElementById('heroTitle'),desc=document.getElementById('heroDesc');if(title)title.textContent=s[0];if(desc)desc.textContent=s[1];document.querySelectorAll('.hero-dot').forEach((d,n)=>d.classList.toggle('on',n===window._heroIndex));if(copy)copy.classList.remove('is-changing')},140)}
function changeHero(step){setHero((window._heroIndex||0)+step)}
function renderTopic(k){let d=DATA[k][LANG],meta=topicMeta[k],more=LANG==='en'?'Learn more':LANG==='es'?'Saber más':'Saiba mais',collapse=LANG==='en'?'Collapse':LANG==='es'?'Contraer':'Recolher';let secs=d.sections.map((sec,i)=>{let extra=buildMoreText(d,sec,i);return `<section class="topic-section"><span class="tag">${i===0?'🟢 '+t('level1'):i<3?'🔵 '+t('level2'):'🟣 '+t('level3')}</span><h2>${sec[0]}</h2><p>${sec[1]}</p><button class="learn-more-btn" type="button" data-more="${more}" data-collapse="${collapse}" onclick="toggleLearnMore(this)">${more} <span class="more-arrow">→</span></button><div class="learn-more-panel">${extra}</div></section>`}).join('');let off=meta[3]?officialLinks(DATA[k]._meta):'';document.getElementById('main').innerHTML=`<div class="topic-head"><div class="breadcrumbs">QA Lab Brasil › ${d.title}</div><div class="ico">${meta[0]}</div><h1>${d.title}</h1><p>${d.subtitle}</p><div class="topic-meta"><span class="level">🟢 ${t('level1')}</span><span class="level">🔵 ${t('level2')}</span><span class="level">🟣 ${t('level3')}</span><span class="level">🗓 ${t('updated')}</span></div></div>${secs}<div class="tip"><b>💡 ${t('tip')}</b><br>${d.qa_tip}</div>${off}<div class="download-box"><h3>📄 ${t('download')}</h3><p>${LANG==='en'?'Download the topic for offline study. Tool guides will progressively include complete installation, configuration and troubleshooting instructions.':LANG==='es'?'Descargue el tema para estudiar offline. Las guías de herramientas incluirán progresivamente instalación, configuración y troubleshooting completos.':'Baixe o tópico para estudo offline. Os guias de ferramentas passarão a incluir instalação, configuração e troubleshooting completos.'}</p><a class="btn primary" href="/pdf/${LANG}/${k}.pdf" download>⬇️ ${t('download')}</a>${QA_INSTALLABLE.has(k)?`<a class="btn" href="/pdf/${LANG}/${k}-installation.pdf" download>🛠️ ${p14Label('Instalação e Configuração','Installation & Setup','Instalación y Configuración')}</a>`:''}</div><section class="topic-section"><h2>🔗 ${t('related')}</h2><div class="related">${Object.keys(DATA).filter(x=>x!==k && topicMeta[x][2]===meta[2]).slice(0,5).map(x=>`<button class="btn" onclick="qaNavigate('${x}')">${topicMeta[x][0]} ${DATA[x][LANG].title}</button>`).join('')}</div></section>`;window.scrollTo(0,0);}
function buildMoreText(d,sec,i){
let labels={pt:['Por que isso importa para QA?','Como aplicar na prática','Boas práticas','Ponto de atenção'],en:['Why does this matter to QA?','How to apply it','Good practices','Watch out'],es:['¿Por qué importa para QA?','Cómo aplicarlo','Buenas prácticas','Punto de atención']}[LANG];
let x=d.insights?.[i]||{};
let cards=[];
if(x.why)cards.push(`<div><b>🎯 ${labels[0]}</b><p>${x.why}</p></div>`);
if(x.apply)cards.push(`<div><b>🧭 ${labels[1]}</b><p>${x.apply}</p></div>`);
if(x.good)cards.push(`<div><b>✅ ${labels[2]}</b><p>${x.good}</p></div>`);
if(x.caution)cards.push(`<div><b>⚠️ ${labels[3]}</b><p>${x.caution}</p></div>`);
return cards.length?`<div class="more-grid">${cards.join('')}</div>`:'';
}
function toggleLearnMore(btn){let p=btn.nextElementSibling,open=p.classList.toggle('open');btn.innerHTML=(open?btn.dataset.collapse:btn.dataset.more)+' <span class="more-arrow">→</span>'; }
function toggleHomeMore(btn){let p=btn.nextElementSibling,open=p.classList.toggle('open');let more=LANG==='en'?'Learn more':LANG==='es'?'Saber más':'Saiba mais',col=LANG==='en'?'Collapse':LANG==='es'?'Contraer':'Recolher';btn.innerHTML=(open?col:more)+' <span class="more-arrow">→</span>'; }
function officialLink(url){return `<div class="download-box"><h3>🌐 ${t('official')}</h3><a class="btn" href="${url}" target="_blank" rel="noopener">${url.replace('https://','')} ↗</a></div>`}
function officialLinks(meta){let site=meta.official,dl=meta.download,docs=meta.docs;let title=LANG==='en'?'Official resources':LANG==='es'?'Recursos oficiales':'Recursos oficiais';let labels=LANG==='en'?['Official site','Installation / download','Documentation']:LANG==='es'?['Sitio oficial','Instalación / descarga','Documentación']:['Site oficial','Instalação / download','Documentação'];let guide=LANG==='en'?'QA Lab installation guide':LANG==='es'?'Guía de instalación QA Lab':'Guia de instalação QA Lab';return `<div class="download-box"><h3>🌐 ${title}</h3><div class="related">${site?`<a class="btn" href="${site}" target="_blank" rel="noopener">🌐 ${labels[0]} ↗</a>`:''}${dl?`<a class="btn" href="${dl}" target="_blank" rel="noopener">⬇️ ${labels[1]} ↗</a>`:''}${docs?`<a class="btn" href="${docs}" target="_blank" rel="noopener">📚 ${labels[2]} ↗</a>`:''}</div></div>`}
function aboutContact(){let a={pt:{title:'Sobre o Autor',body:'Rodrigo Ferrari é profissional de Quality Assurance e Engenharia de Qualidade com mais de 12 anos de experiência em qualidade de software, atuando em projetos de diferentes portes, tecnologias e segmentos. Ao longo da carreira, participou de projetos nos setores Financeiro e Bancário (Bradesco e Banco Original), Saúde e Indústria Farmacêutica (Johnson & Johnson), Telecomunicações (Vivo e Claro), Mídia e Entretenimento (Rede Globo e SKY), Meios de Pagamento (Cielo) e Automotivo (Citroën). Sua trajetória inclui também projetos internacionais para México e Costa Rica. É formado em Análise e Desenvolvimento de Sistemas e atualmente cursa Pós-Graduação em Gestão de Projetos. Sua experiência abrange estratégia e liderança de QA, Web, Mobile, APIs, integrações, UAT, automação, gestão de defeitos, métricas e IA aplicada a QA, com tecnologias como Playwright, Python, Selenium, Robot Framework, Jira, Xray, Salesforce e Salesforce Commerce Cloud. O QA Lab Brasil nasce dessa experiência para compartilhar conhecimento prático, ferramentas e conceitos de Quality Engineering com profissionais em diferentes momentos da carreira.',contact:'Contato',contactTitle:'Fale com o QA Lab',contactSub:'Envie uma dúvida, sugestão, feedback ou reporte um problema.',name:'Nome',subject:'Assunto',opts:['Dúvida','Sugestão de conteúdo','Reportar problema','Parceria','Feedback'],message:'Mensagem',send:'Enviar mensagem'},en:{title:'About the Author',body:'Rodrigo Ferrari is a Quality Assurance and Quality Engineering professional with more than 12 years of software quality experience across projects of different sizes, technologies and industries. Throughout his career, he has contributed to projects in Financial Services and Banking (Bradesco and Banco Original), Healthcare and Pharmaceuticals (Johnson & Johnson), Telecommunications (Vivo and Claro), Media and Entertainment (Rede Globo and SKY), Payments (Cielo), and Automotive (Citroën). His background also includes international projects for Mexico and Costa Rica. He holds a degree in Systems Analysis and Development and is currently pursuing a postgraduate degree in Project Management. His experience covers QA strategy and leadership, Web, Mobile, APIs, integrations, UAT, test automation, defect management, quality metrics and AI applied to QA, using technologies such as Playwright, Python, Selenium, Robot Framework, Jira, Xray, Salesforce and Salesforce Commerce Cloud. QA Lab Brasil was created from this experience to share practical knowledge, tools and Quality Engineering concepts with professionals at different stages of their careers.',contact:'Contact',contactTitle:'Contact QA Lab',contactSub:'Send a question, content suggestion, feedback or report a problem.',name:'Name',subject:'Subject',opts:['Question','Content suggestion','Report a problem','Partnership','Feedback'],message:'Message',send:'Send message'},es:{title:'Sobre el Autor',body:'Rodrigo Ferrari es profesional de Quality Assurance e Ingeniería de Calidad con más de 12 años de experiencia en calidad de software, participando en proyectos de diferentes tamaños, tecnologías y sectores. A lo largo de su carrera, ha participado en proyectos de Servicios Financieros y Bancarios (Bradesco y Banco Original), Salud e Industria Farmacéutica (Johnson & Johnson), Telecomunicaciones (Vivo y Claro), Medios y Entretenimiento (Rede Globo y SKY), Medios de Pago (Cielo) y Automotriz (Citroën). Su trayectoria también incluye proyectos internacionales para México y Costa Rica. Es graduado en Análisis y Desarrollo de Sistemas y actualmente cursa un Posgrado en Gestión de Proyectos. Su experiencia abarca estrategia y liderazgo de QA, Web, Mobile, APIs, integraciones, UAT, automatización, gestión de defectos, métricas de calidad e IA aplicada a QA, con tecnologías como Playwright, Python, Selenium, Robot Framework, Jira, Xray, Salesforce y Salesforce Commerce Cloud. QA Lab Brasil nace de esta experiencia para compartir conocimientos prácticos, herramientas y conceptos de Quality Engineering con profesionales en diferentes etapas de su carrera.',contact:'Contacto',contactTitle:'Contacte QA Lab',contactSub:'Envíe una duda, sugerencia, feedback o reporte un problema.',name:'Nombre',subject:'Asunto',opts:['Duda','Sugerencia de contenido','Reportar problema','Colaboración','Feedback'],message:'Mensaje',send:'Enviar mensaje'}}[LANG];return `<section class="section"><div class="author-contact"><article class="author-card"><div class="ico">👨‍💻</div><h3>${a.title}</h3><p>${a.body}</p><div class="actions"><a class="btn" href="https://www.linkedin.com/in/rodrigo-martins-ferrari-02b49449/" target="_blank" rel="noopener">💼 LinkedIn ↗</a><a class="btn" href="https://github.com/Rodrigoferrari1" target="_blank" rel="noopener">💻 GitHub ↗</a><a class="btn" href="mailto:contato@qualityassurancebrasil.com.br?subject=Contato%20%E2%80%94%20QA%20Lab%20Brasil">✉️ ${a.contact}</a></div></article><article class="contact-card"><div class="ico">📩</div><h3>${a.contactTitle}</h3><p>${a.contactSub}</p><form name="qa-lab-contact" method="POST" data-netlify="true" netlify-honeypot="bot-field" onsubmit="return submitContact(event)" class="contact-grid"><input type="hidden" name="form-name" value="qa-lab-contact"><p hidden><label>Bot <input name="bot-field"></label></p><input name="name" required placeholder="${a.name}"><input name="email" type="email" required placeholder="E-mail"><select name="subject" class="wide" aria-label="${a.subject}">${a.opts.map(x=>`<option>${x}</option>`).join('')}</select><textarea name="message" required class="wide" placeholder="${a.message}"></textarea><button class="btn primary wide" type="submit">📨 ${a.send}</button></form><div class="demo-note" id="contactStatus">${LANG==='en'?'On Netlify, submissions are captured by Netlify Forms.':LANG==='es'?'En Netlify, los envíos son capturados por Netlify Forms.':'No Netlify, os envios são capturados pelo Netlify Forms.'}</div></article></div></section>`}
function submitContact(e){e.preventDefault();let form=e.target,status=document.getElementById('contactStatus');if(location.protocol==='file:'){status.textContent=LANG==='en'?'Preview mode: form submission is enabled after Netlify publication.':LANG==='es'?'Modo preview: el envío se habilita después de publicar en Netlify.':'Modo preview: o envio é habilitado após a publicação no Netlify.';return false}let body=new URLSearchParams(new FormData(form)).toString();fetch('/',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body}).then(()=>{status.textContent=LANG==='en'?'Message sent successfully.':LANG==='es'?'Mensaje enviado correctamente.':'Mensagem enviada com sucesso.';qaTrackEvent('contact_submit',{subject:form.elements.subject?.value||''});form.reset()}).catch(()=>status.textContent=LANG==='en'?'Could not send the message. Please try again.':LANG==='es'?'No fue posible enviar el mensaje. Inténtelo nuevamente.':'Não foi possível enviar a mensagem. Tente novamente.');return false}

function search(q){let box=document.getElementById('searchResults');q=q.trim().toLowerCase();if(!q){box.classList.remove('open');return}let out=[];for(let[k,v]of Object.entries(DATA)){let d=v[LANG];let text=[d.title,d.subtitle,d.qa_tip,...d.sections.flat()].join(' ').toLowerCase();if(text.includes(q))out.push([k,d]);}box.innerHTML=out.length?out.map(([k,d])=>`<div class="result" onclick="qaNavigate('${k}');document.getElementById('searchResults').classList.remove('open')"><b>${topicMeta[k][0]} ${d.title}</b><br><small>${d.subtitle}</small></div>`).join(''):`<div class="result">${LANG==='en'?'No results':LANG==='es'?'Sin resultados':'Nenhum resultado'}</div>`;box.classList.add('open');}

