const SEARCH_ALIASES={pt:{aceitação:['uat','acceptance'],aceitação:['uat','acceptance'],regressão:['regression'],regressão:['regression'],automação:['automation'],automação:['automation'],banco:['sql','database'],erro:['bug','defect','failure'],celular:['mobile','appium'],métricas:['metrics','power bi'],métricas:['metrics','power bi']},en:{acceptance:['uat'],defect:['bug','failure'],database:['sql','data'],mobile:['appium','browserstack'],metrics:['power bi','analytics']},es:{aceptacion:['uat'],aceptación:['uat'],regresion:['regression'],regresión:['regression'],automatizacion:['automation'],automatización:['automation'],datos:['sql','database'],movil:['mobile','appium'],móvil:['mobile','appium'],métricas:['metrics','power bi'],métricas:['metrics','power bi']}};
function expandedTerms(q){let raw=q.toLowerCase().trim().split(/\s+/).filter(Boolean),a=SEARCH_ALIASES[LANG]||{};return [...new Set(raw.flatMap(x=>[x,...(a[x]||[])]))]}
function search(q){let box=document.getElementById('searchResults');let terms=expandedTerms(q);if(!terms.length){box.classList.remove('open');return}let out=[];for(let[k,v]of Object.entries(DATA)){let d=v[LANG],text=[d.title,d.subtitle,d.qa_tip,...d.sections.flat()].join(' ').toLowerCase(),score=terms.reduce((n,w)=>n+(text.includes(w)?2:0)+(d.title.toLowerCase().includes(w)?3:0),0);if(score)out.push([score,k,d]);}out.sort((a,b)=>b[0]-a[0]);box.innerHTML=out.length?out.slice(0,12).map(([,k,d])=>`<div class="result" onclick="qaNavigate('${k}');document.getElementById('searchResults').classList.remove('open')"><b>${topicMeta[k][0]} ${d.title}</b><br><small>${d.subtitle}</small></div>`).join(''):`<div class="result">${LANG==='en'?'No matching topic found.':LANG==='es'?'No se encontró un tema relacionado.':'Nenhum tópico relacionado encontrado.'}</div>`;box.classList.add('open')}
function updateLanguagePicker(){const sb=document.getElementById('searchAction');if(sb)sb.textContent=LANG==='en'?'Search':LANG==='es'?'Buscar':'Pesquisar';const bt=document.getElementById('backToTop');if(bt){bt.setAttribute('aria-label',LANG==='en'?'Back to top':LANG==='es'?'Volver arriba':'Voltar ao topo');bt.title=bt.getAttribute('aria-label');}let b=document.getElementById('languagePickerBtn');if(!b)return;let x={pt:['BR Português','pt'],en:['US English','en'],es:['ES Español','es']}[LANG];b.innerHTML=`<span class="flag-circle flag-${x[1]}" aria-hidden="true"></span><span>${x[0]}</span> <b>⌄</b>`}
function wsVal(id){return (document.getElementById(id)?.value||'').trim()}
function wsCopy(id){let el=document.getElementById(id);if(!el)return;navigator.clipboard?.writeText(el.value||el.textContent||'')}
function wsDownload(id,name){let el=document.getElementById(id);if(!el)return;let blob=new Blob([el.value||el.textContent||''],{type:'text/plain;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();URL.revokeObjectURL(a.href)}
function wsTestCase(){let out=`TÍTULO: ${wsVal('tcTitle')||'[Título do caso]'}\nPRÉ-CONDIÇÕES: ${wsVal('tcPre')||'[Pré-condições]'}\n\nSTEP | DATA | EXPECTED RESULT\n1. ${wsVal('tcStep')||'[Ação do usuário]'} | ${wsVal('tcData')||'[Dados]'} | ${wsVal('tcExpected')||'[Resultado esperado]'}`;document.getElementById('tcOut').value=out}
function wsBug(){let out=`SUMMARY: ${wsVal('bugSummary')||'[Resumo objetivo]'}\nENVIRONMENT: ${wsVal('bugEnv')||'[Ambiente / browser / device]'}\nSEVERITY: ${wsVal('bugSeverity')||'Medium'}\n\nSTEPS TO REPRODUCE:\n${wsVal('bugSteps')||'1. [Passo]'}\n\nEXPECTED RESULT:\n${wsVal('bugExpected')||'[Esperado]'}\n\nACTUAL RESULT:\n${wsVal('bugActual')||'[Atual]'}`;document.getElementById('bugOut').value=out}
function wsScenarios(){let f=wsVal('scenarioFeature')||'funcionalidade';let out=`Cenários sugeridos para: ${f}\n\n1. Fluxo principal / happy path\n2. Campos obrigatórios e dados ausentes\n3. Dados inválidos e formatos incorretos\n4. Valores de limite / boundary\n5. Permissões e perfis de acesso\n6. Estados anteriores e posteriores\n7. Integrações e tratamento de erro\n8. Persistência e consistência dos dados\n9. Responsividade / compatibilidade quando aplicável\n10. Recuperação após falha e mensagens ao usuário`;document.getElementById('scenarioOut').value=out}
function wsData(){let n=Math.floor(Math.random()*900000+100000),d=new Date(Date.now()+86400000*30).toISOString().slice(0,10);let out=`Nome: Usuário QA ${n}\nE-mail: qa.${n}@example.com\nTelefone: 119${String(n).padStart(8,'0').slice(0,8)}\nID fictício: QA-${n}\nData futura: ${d}\nValor válido: 99.90\nValor limite: 0.01\nTexto especial: QA Teste !@# ${n}`;document.getElementById('dataOut').value=out}
function renderWorkspace(){let L={pt:['QA Workspace','Ferramentas práticas para criar artefatos e apoiar atividades recorrentes de Quality Assurance. Os dados permanecem somente neste navegador.','Gerador de Caso de Teste','Gerador de Bug Report','Gerador de Cenários','Massa de Teste','Checklists rápidos','Copiar','Exportar TXT','Gerar'],en:['QA Workspace','Practical tools to create artifacts and support recurring Quality Assurance activities. Data stays only in this browser.','Test Case Generator','Bug Report Generator','Scenario Generator','Test Data','Quick checklists','Copy','Export TXT','Generate'],es:['QA Workspace','Herramientas prácticas para crear artefactos y apoyar actividades recurrentes de Quality Assurance. Los datos permanecen solo en este navegador.','Generador de Caso de Prueba','Generador de Bug Report','Generador de Escenarios','Datos de Prueba','Checklists rápidos','Copiar','Exportar TXT','Generar']}[LANG];document.getElementById('main').innerHTML=`<div class="topic-head"><div class="breadcrumbs">QA Lab Brasil › ${L[0]}</div><div class="ico">🧰</div><h1>${L[0]}</h1><p>${L[1]}</p></div><div class="tool-grid"><section class="tool-card"><h2>🧪 ${L[2]}</h2><input id="tcTitle" placeholder="Título"><input id="tcPre" placeholder="Pré-condições"><input id="tcStep" placeholder="Step"><input id="tcData" placeholder="Data"><input id="tcExpected" placeholder="Expected Result"><button class="btn primary" onclick="wsTestCase()">⚙️ ${L[8]}</button><textarea id="tcOut" class="code-output" rows="8" readonly></textarea><div class="actions"><button class="btn" onclick="wsCopy('tcOut')">📋 ${L[6]}</button><button class="btn" onclick="wsDownload('tcOut','qa-lab-test-case.txt')">⬇️ ${L[7]}</button></div></section><section class="tool-card"><h2>🐞 ${L[3]}</h2><input id="bugSummary" placeholder="Summary"><input id="bugEnv" placeholder="Environment"><select id="bugSeverity"><option>Low</option><option selected>Medium</option><option>High</option><option>Critical</option></select><textarea id="bugSteps" placeholder="Steps to Reproduce"></textarea><input id="bugExpected" placeholder="Expected Result"><input id="bugActual" placeholder="Actual Result"><button class="btn primary" onclick="wsBug()">⚙️ ${L[8]}</button><textarea id="bugOut" class="code-output" rows="10" readonly></textarea><div class="actions"><button class="btn" onclick="wsCopy('bugOut')">📋 ${L[6]}</button><button class="btn" onclick="wsDownload('bugOut','qa-lab-bug-report.txt')">⬇️ ${L[7]}</button></div></section><section class="tool-card"><h2>🎯 ${L[4]}</h2><input id="scenarioFeature" placeholder="Funcionalidade / requisito"><button class="btn primary" onclick="wsScenarios()">⚙️ ${L[8]}</button><textarea id="scenarioOut" class="code-output" rows="11" readonly></textarea><div class="actions"><button class="btn" onclick="wsCopy('scenarioOut')">📋 ${L[6]}</button><button class="btn" onclick="wsDownload('scenarioOut','qa-lab-scenarios.txt')">⬇️ ${L[7]}</button></div></section><section class="tool-card"><h2>🧬 ${L[5]}</h2><p>${LANG==='en'?'Generate fictitious data for non-production tests.':LANG==='es'?'Genere datos ficticios para pruebas fuera de producción.':'Gere dados fictícios para testes fora de produção.'}</p><button class="btn primary" onclick="wsData()">🎲 ${L[8]}</button><textarea id="dataOut" class="code-output" rows="10" readonly></textarea><div class="actions"><button class="btn" onclick="wsCopy('dataOut')">📋 ${L[6]}</button><button class="btn" onclick="wsDownload('dataOut','qa-lab-test-data.txt')">⬇️ ${L[7]}</button></div></section></div><section class="tool-card" style="margin-top:16px"><h2>☑️ ${L[6]}</h2><div class="workspace-checklists"><div><h3>🔥 Smoke / Release</h3>${['Fluxo crítico executado','Bugs críticos revisados','Integrações validadas','Rollback conhecido','Evidências anexadas'].map(x=>`<label class="check-row"><input type="checkbox"> ${x}</label>`).join('')}</div><div><h3>🔌 API</h3>${['Status code','Schema/contrato','Autenticação','Headers','Dados e efeitos colaterais'].map(x=>`<label class="check-row"><input type="checkbox"> ${x}</label>`).join('')}</div><div><h3>🌐 Web</h3>${['Fluxo funcional','Responsividade','Console/Network','Acessibilidade básica','Cross-browser'].map(x=>`<label class="check-row"><input type="checkbox"> ${x}</label>`).join('')}</div><div><h3>📱 Mobile</h3>${['Android/iOS','Permissões','Orientação','Rede/interrupções','Device real/emulador'].map(x=>`<label class="check-row"><input type="checkbox"> ${x}</label>`).join('')}</div></div></section>`;window.scrollTo(0,0)}
