function saveWsChecks(){localStorage.setItem('qalab-release-checks',JSON.stringify([...document.querySelectorAll('.workspace-grid input[type=checkbox]')].map(x=>x.checked)))}
function addCurrentFav(){let h=qaRouteKey();if(!DATA[h]){h='qa'}let f=JSON.parse(localStorage.getItem('qalab-favs')||'[]');if(!f.includes(h))f.push(h);localStorage.setItem('qalab-favs',JSON.stringify(f));renderWorkspace()}
function clearWorkspace(){['qalab-notes','qalab-release-checks','qalab-favs'].forEach(k=>localStorage.removeItem(k));renderWorkspace()}
function askAssistant(){let inp=document.getElementById('chatInput'),q=inp.value.trim();if(!q)return;let terms=expandedTerms(q),scores=[];for(let[k,v]of Object.entries(DATA)){let d=v[LANG],txt=[d.title,d.subtitle,d.qa_tip,...d.sections.flat()].join(' ').toLowerCase(),score=terms.reduce((n,w)=>n+(txt.includes(w)?2:0)+(d.title.toLowerCase().includes(w)?3:0),0);if(score)scores.push([score,k,d])}scores.sort((a,b)=>b[0]-a[0]);let msg=document.getElementById('chatMsg');if(scores.length){let[,k,d]=scores[0],matches=d.sections.filter(s=>terms.some(w=>(s[0]+' '+s[1]).toLowerCase().includes(w))).slice(0,2),body=(matches.length?matches:d.sections.slice(0,1)).map(s=>`<b>${s[0]}</b><br>${s[1]}`).join('<br><br>');msg.innerHTML=`<b>${topicMeta[k][0]} ${d.title}</b><br>${body}<br><br><button class="btn" onclick="qaNavigate('${k}');document.getElementById('chatbox').classList.remove('open')">${LANG==='en'?'Open full topic':LANG==='es'?'Abrir tema completo':'Abrir tópico completo'} →</button>`}else msg.textContent=LANG==='en'?'I could not find this subject in the QA Lab knowledge base yet.':LANG==='es'?'Todavía no encontré este tema en la base de conocimiento de QA Lab.':'Ainda não encontrei esse assunto na base de conhecimento do QA Lab.';inp.value=''}
const oldRouteV22=route;route=function(){navLabels();let h=qaRouteKey();if(h==='workspace')renderWorkspace();else if(h==='toolkit')renderToolkit();else if(h==='glossary')renderGlossary();else if(h==='how-to-test')renderHowToTest();else if(h==='api-lab')renderApiLab();else if(h==='bug-clinic')renderBugClinic();else if(h==='qa-shop')renderQaShop();else if(h==='simulators')renderSimulators();else if(h==='test-data-generator')renderTestDataGenerator();else if(h&&DATA[h])renderTopic(h);else renderHome();}

function scrollInstallGuide(){let keys=['instala','install','configura','setup','pré-requis','prerequis','requisit'];let secs=[...document.querySelectorAll('.topic-section')];let hit=secs.find(x=>keys.some(k=>(x.querySelector('h2')?.textContent||'').toLowerCase().includes(k)));(hit||secs[0])?.scrollIntoView({behavior:'smooth',block:'start'});}


