const P16_EX={
 playground:{pt:[
  ['Básico','Login','Uma tela de login possui e-mail, senha e botão Entrar. Liste pelo menos 6 cenários de teste.','Inclua fluxo válido, credenciais inválidas, campos vazios, formato de e-mail, senha incorreta e comportamento da sessão.'],
  ['Intermediário','Cupom de desconto','Cupom válido aplica 10%, expirado é rejeitado e não pode ser aplicado duas vezes. Priorize cenários para Smoke e regressão.','Smoke: aplicação válida e bloqueio de cupom expirado. Regressão: duplicidade, arredondamento, remoção, combinação com outros descontos e persistência.'],
  ['Profissional','Risco de release','Checkout recebeu mudança em pagamento e endereço. Há pouco tempo para regressão. Defina uma estratégia.','Priorize pagamento, criação do pedido, idempotência, endereço, integrações e fluxo completo. Use risco, impacto e histórico de defeitos para reduzir escopo com segurança.']
 ],en:[['Basic','Login','A login screen has email, password and Sign in. List at least 6 test scenarios.','Cover valid flow, invalid credentials, empty fields, email format, wrong password and session behavior.'],['Intermediate','Discount coupon','A valid coupon applies 10%, expired is rejected and cannot be applied twice. Prioritize Smoke and regression.','Smoke: valid application and expired coupon rejection. Regression: duplicate use, rounding, removal, combinations and persistence.'],['Professional','Release risk','Checkout changed payment and address with little regression time. Define a strategy.','Prioritize payment, order creation, idempotency, address, integrations and end-to-end flow using risk and defect history.']],es:[['Básico','Login','Una pantalla de login tiene e-mail, contraseña y Entrar. Liste al menos 6 escenarios.','Incluya flujo válido, credenciales inválidas, campos vacíos, formato, contraseña incorrecta y sesión.'],['Intermedio','Cupón','Cupón válido aplica 10%, vencido es rechazado y no puede aplicarse dos veces. Priorice Smoke y regresión.','Smoke: aplicación válida y rechazo del vencido. Regresión: duplicidad, redondeo, eliminación, combinaciones y persistencia.'],['Profesional','Riesgo de release','Checkout cambió pago y dirección con poco tiempo. Defina estrategia.','Priorice pago, pedido, idempotencia, dirección, integraciones y E2E usando riesgo e histórico.']]},
 'api-lab':{pt:[['Básico','Status codes','Uma API GET /users/123 retorna usuário existente. Quais respostas validar para sucesso, não encontrado e acesso sem token?','200 para sucesso, 404 quando o recurso não existe e 401 quando autenticação é exigida e está ausente/inválida.'],['Intermediário','POST idempotente','Uma API cria pedidos. Quais riscos testar ao repetir a mesma requisição após timeout?','Verifique duplicidade, chave de idempotência, resposta consistente, efeitos no estoque/pagamento e rastreabilidade.'],['Profissional','Contrato','Um campo obrigatório do response mudou de number para string. O front quebra. Que camada deveria detectar?','Contract/schema testing deve detectar a quebra antes do E2E; complemente com integração e monitoramento de compatibilidade.']],en:[['Basic','Status codes','GET /users/123 returns an existing user. What responses should be validated for success, not found and missing token?','200 success, 404 missing resource and 401 when authentication is required and missing/invalid.'],['Intermediate','Idempotent POST','An API creates orders. What risks should be tested when retrying after timeout?','Check duplicates, idempotency key, consistent response, inventory/payment effects and traceability.'],['Professional','Contract','A required response field changed from number to string and breaks the front end. What layer should catch it?','Contract/schema testing should catch it before E2E, complemented by integration tests.']],es:[['Básico','Status codes','GET /users/123 devuelve usuario existente. ¿Qué respuestas validar para éxito, no encontrado y sin token?','200 éxito, 404 recurso inexistente y 401 autenticación ausente/inválida.'],['Intermedio','POST idempotente','Una API crea pedidos. ¿Qué riesgos probar al repetir después de timeout?','Duplicidad, clave de idempotencia, respuesta, stock/pago y trazabilidad.'],['Profesional','Contrato','Un campo obligatorio cambió de number a string y rompe el front. ¿Qué capa debe detectarlo?','Contract/schema testing debe detectarlo antes de E2E.']]},
 'bug-clinic':{pt:[['Básico','Título fraco','Melhore: “Botão não funciona”.','Exemplo: “Checkout - botão Finalizar compra não responde após preencher cartão válido”.'],['Intermediário','Reprodução','Um bug ocorre somente no Safari iOS após voltar do PayPal. Quais dados não podem faltar?','Versão iOS/Safari, device, ambiente, conta/dados, passos exatos, URL, evidência, esperado/atual e frequência.'],['Profissional','Severidade','Erro visual no logo e pagamento duplicado foram encontrados. Compare severidade e prioridade.','Pagamento duplicado tende a alta/crítica severidade e prioridade; logo visual normalmente baixa severidade, embora prioridade possa variar pelo negócio.']],en:[['Basic','Weak title','Improve: “Button does not work”.','Example: “Checkout - Place order button does not respond after valid card data”.'],['Intermediate','Reproduction','A bug occurs only on iOS Safari after returning from PayPal. What data is mandatory?','iOS/Safari version, device, environment, data, exact steps, URL, evidence, expected/actual and frequency.'],['Professional','Severity','A logo visual issue and duplicate payment are found. Compare severity and priority.','Duplicate payment is usually high/critical severity; logo visual is usually low severity, while business priority may vary.']],es:[['Básico','Título débil','Mejore: “Botón no funciona”.','Ejemplo: “Checkout - Finalizar compra no responde después de tarjeta válida”.'],['Intermedio','Reproducción','Bug solo en Safari iOS después de PayPal. ¿Qué datos no pueden faltar?','Versión, device, ambiente, datos, pasos, URL, evidencia, esperado/actual y frecuencia.'],['Profesional','Severidad','Problema visual en logo y pago duplicado. Compare severidad y prioridad.','Pago duplicado suele ser alto/crítico; logo visual suele ser bajo, con prioridad variable.']]},
 'code-lab':{pt:[['Básico','Locator','Um botão possui data-testid="submit-order". Qual estratégia de locator é mais estável?','Prefira um locator semântico/estável como getByTestId("submit-order") quando o contrato de test id é adotado pelo time.'],['Intermediário','Flaky test','Teste falha porque usa sleep(5000) esperando uma resposta variável. Como melhorar?','Espere uma condição observável: response, elemento visível/habilitado ou estado específico; evite sleeps fixos.'],['Profissional','Arquitetura','Suíte E2E repete login em 300 testes. Como reduzir custo sem esconder riscos?','Use fixtures/setup, estado autenticado reutilizável quando seguro, APIs para preparação e mantenha alguns E2E reais de autenticação.']],en:[['Basic','Locator','A button has data-testid="submit-order". What locator is stable?','Prefer a semantic/stable locator such as getByTestId when the team treats test ids as a contract.'],['Intermediate','Flaky test','A test uses sleep(5000) for a variable response. Improve it.','Wait for an observable condition: response, visible/enabled element or expected state.'],['Professional','Architecture','An E2E suite repeats login in 300 tests. Reduce cost without hiding risk.','Use fixtures/setup, reusable auth state when safe, APIs for setup, while retaining some true auth E2E tests.']],es:[['Básico','Locator','Botón con data-testid="submit-order". ¿Qué locator es estable?','Prefiera locator semántico/estable como getByTestId cuando el equipo usa test ids como contrato.'],['Intermedio','Flaky test','Prueba usa sleep(5000) esperando respuesta variable. Mejore.','Espere condición observable: response, elemento visible/habilitado o estado esperado.'],['Profesional','Arquitectura','Suite E2E repite login en 300 pruebas. ¿Cómo reducir costo?','Use fixtures/setup, estado autenticado y APIs de preparación, manteniendo algunos E2E reales.']]},
 'sql-lab':{pt:[['Básico','Filtro','Tabela orders possui status. Escreva a intenção da query para buscar pedidos CANCELLED.','SELECT * FROM orders WHERE status = \'CANCELLED\';'],['Intermediário','Join','Valide se todo pedido possui cliente existente usando orders.customer_id e customers.id.','Use LEFT JOIN de orders para customers e filtre customers.id IS NULL para localizar referências órfãs.'],['Profissional','Consistência','Pagamento aprovado existe, mas pedido não foi criado. Como investigar no banco?','Correlacione IDs/transação, timestamps, tabelas de pagamento/pedido, filas/outbox e logs; valide atomicidade e eventual consistency.']],en:[['Basic','Filter','orders has status. Query cancelled orders.','SELECT * FROM orders WHERE status = \'CANCELLED\';'],['Intermediate','Join','Validate every order has an existing customer.','LEFT JOIN orders to customers and filter customers.id IS NULL to find orphan references.'],['Professional','Consistency','Approved payment exists but order is missing. Investigate.','Correlate transaction IDs, timestamps, payment/order tables, queues/outbox and logs; validate consistency.']],es:[['Básico','Filtro','orders tiene status. Busque pedidos CANCELLED.','SELECT * FROM orders WHERE status = \'CANCELLED\';'],['Intermedio','Join','Valide que todo pedido tenga cliente.','LEFT JOIN orders con customers y filtre customers.id IS NULL.'],['Profesional','Consistencia','Pago aprobado existe pero pedido no. Investigue.','Correlacione IDs, timestamps, tablas, colas/outbox y logs; valide consistencia.']]}
};
function p16Esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function renderPracticeLab(key){const m=P16_LABS[key],head=m[LANG]||m.pt,ex=(P16_EX[key]||P16_EX.playground)[LANG]||P16_EX[key].pt;const labels={pt:['Exercício','Sua resposta / anotações','Ver solução comentada','Ocultar solução','Solução comentada','Próximo nível'],en:['Exercise','Your answer / notes','Show commented solution','Hide solution','Commented solution','Next level'],es:['Ejercicio','Su respuesta / notas','Ver solución comentada','Ocultar solución','Solución comentada','Siguiente nivel']}[LANG];document.getElementById('main').innerHTML=`<div class="topic-head"><div class="breadcrumbs">QA Lab Brasil › ${head[0]}</div><div class="ico">${m.icon}</div><h1>${head[0]}</h1><p>${head[1]}</p></div><div class="lab-levels">${ex.map((x,i)=>`<article class="lab-exercise" id="lab-${i}"><span class="tag">${i===0?'🟢':i===1?'🔵':'🟣'} ${x[0]}</span><h2>${labels[0]} ${i+1}: ${x[1]}</h2><p>${x[2]}</p><textarea rows="5" placeholder="${labels[1]}"></textarea><div class="actions"><button class="btn primary" onclick="p16ToggleSolution(${i},this)">💡 ${labels[2]}</button></div><div class="lab-solution" id="lab-sol-${i}" hidden><h3>✅ ${labels[4]}</h3><p>${p16Esc(x[3])}</p>${i<ex.length-1?`<button class="btn" onclick="document.getElementById('lab-${i+1}').scrollIntoView({behavior:'smooth'})">${labels[5]} →</button>`:''}</div></article>`).join('')}</div>`;window.scrollTo(0,0)}
function p16ToggleSolution(i,b){let s=document.getElementById('lab-sol-'+i),open=!s.hidden;s.hidden=open;let L={pt:['Ver solução comentada','Ocultar solução'],en:['Show commented solution','Hide solution'],es:['Ver solución comentada','Ocultar solución']}[LANG];b.innerHTML='💡 '+(open?L[0]:L[1])}
const routeP16=route;route=function(){navLabels();let h=qaRouteKey();if(P16_LABS[h])renderPracticeLab(h);else if(h==='sql-lab')renderPracticeLab('sql-lab');else routeP16()}
const P17_GLOSSARY={
 pt:{API:'Interface para comunicação entre sistemas e serviços.',Endpoint:'Endereço de uma operação disponibilizada por uma API.',Payload:'Dados enviados ou recebidos em uma requisição.',Mock:'Substituto controlado de uma dependência real durante testes.',Stub:'Resposta controlada usada para simular uma dependência.',Fixture:'Dados ou preparação reutilizável usada na execução de testes.',Locator:'Estratégia usada pela automação para encontrar um elemento.',Headless:'Execução de navegador sem interface gráfica visível.',Pipeline:'Fluxo automatizado de build, testes e entrega.',Artifact:'Arquivo ou evidência produzida por uma execução ou pipeline.','Flaky test':'Teste automatizado com resultado inconsistente sem mudança relevante no produto.','Shift-left':'Prática de antecipar atividades de qualidade para etapas mais cedo do desenvolvimento.',Idempotência:'Propriedade em que repetir uma operação produz o mesmo efeito esperado.',Contrato:'Estrutura e regras esperadas na comunicação entre sistemas.',Regression:'Validação de que mudanças não afetaram funcionalidades existentes.',UAT:'Teste de Aceitação do Usuário ou do negócio antes da liberação.'},
 en:{API:'Interface used for communication between systems and services.',Endpoint:'Address of an operation exposed by an API.',Payload:'Data sent or received in a request.',Mock:'Controlled replacement for a real dependency during testing.',Stub:'Controlled response used to simulate a dependency.',Fixture:'Reusable data or setup used during test execution.',Locator:'Strategy automation uses to find an element.',Headless:'Browser execution without a visible graphical interface.',Pipeline:'Automated flow for build, tests and delivery.',Artifact:'File or evidence produced by an execution or pipeline.','Flaky test':'Automated test with inconsistent results without a relevant product change.','Shift-left':'Practice of moving quality activities earlier in development.',Idempotency:'Property where repeating an operation produces the same expected effect.',Contract:'Expected structure and rules for communication between systems.',Regression:'Validation that changes did not affect existing functionality.',UAT:'User Acceptance Testing before release.'},
 es:{API:'Interfaz para comunicación entre sistemas y servicios.',Endpoint:'Dirección de una operación expuesta por una API.',Payload:'Datos enviados o recibidos en una solicitud.',Mock:'Sustituto controlado de una dependencia real durante las pruebas.',Stub:'Respuesta controlada usada para simular una dependencia.',Fixture:'Datos o preparación reutilizable para ejecutar pruebas.',Locator:'Estrategia usada por la automatización para encontrar un elemento.',Headless:'Ejecución del navegador sin interfaz gráfica visible.',Pipeline:'Flujo automatizado de build, pruebas y entrega.',Artifact:'Archivo o evidencia producida por una ejecución o pipeline.','Flaky test':'Prueba automatizada con resultado inconsistente sin cambio relevante en el producto.','Shift-left':'Práctica de anticipar actividades de calidad a etapas tempranas.',Idempotencia:'Propiedad donde repetir una operación produce el mismo efecto esperado.',Contrato:'Estructura y reglas esperadas en la comunicación entre sistemas.',Regresión:'Validación de que los cambios no afectaron funcionalidades existentes.',UAT:'Prueba de Aceptación del Usuario antes de la liberación.'}
};
Object.assign(SEARCH_ALIASES.pt,{bug:['defeito','erro','falha'],defeito:['bug','erro','falha'],bdd:['cucumber'],qc:['alm','quality','center'],quality:['qa'],teste:['testing'],api:['rest','http'],sql:['database','banco'],playwright:['automation','automação'],spring:['java','boot'],acessibilidade:['accessibility','axe','wave'],desempenho:['performance','jmeter','k6']});
Object.assign(SEARCH_ALIASES.en,{bug:['defect','error','failure'],bdd:['cucumber'],qc:['alm','quality center'],qa:['quality'],api:['rest','http'],sql:['database'],accessibility:['axe','wave'],performance:['jmeter','k6']});
Object.assign(SEARCH_ALIASES.es,{bug:['defecto','error','falla'],defecto:['bug','error'],bdd:['cucumber'],qc:['alm','quality center'],qa:['calidad'],api:['rest','http'],sql:['database','datos'],accesibilidad:['accessibility','axe','wave'],rendimiento:['performance','jmeter','k6']});
function p17Kind(k){if(/lab|clinic|playground|workspace|toolkit|how-to-test/.test(k))return 'lab';if(DATA[k]?._meta?.official||DATA[k]?._meta?.download||DATA[k]?._meta?.docs)return 'tool';return 'content'}
function p17KindLabel(kind){let m={pt:{content:'Conteúdos',tool:'Ferramentas',lab:'Laboratórios & Recursos'},en:{content:'Content',tool:'Tools',lab:'Labs & Resources'},es:{content:'Contenidos',tool:'Herramientas',lab:'Laboratorios y Recursos'}};return m[LANG][kind]}
function qaNorm(x){return String(x||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim()}
function qaWhole(text,term){let esc=term.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');return new RegExp('(^|[^a-z0-9])'+esc+'([^a-z0-9]|$)','i').test(text)}
function qaSearchScore(k,d,q){let nq=qaNorm(q),title=qaNorm(d.title),key=qaNorm(k.replaceAll('-',' ')),aliases=(SEARCH_ALIASES[LANG]||{}),terms=expandedTerms(q).map(qaNorm),text=qaNorm([d.subtitle,d.qa_tip,...d.sections.flat()].join(' '));let score=0;if(title===nq)score+=1000;if(key===nq)score+=950;if(title.startsWith(nq))score+=500;if(qaWhole(title,nq))score+=400;for(let w of terms){if(title===w)score+=300;else if(qaWhole(title,w))score+=120;else if(title.includes(w))score+=40;if(qaWhole(text,w))score+=15;else if(text.includes(w))score+=3;}return score}
search=function(q){let box=document.getElementById('searchResults');if(!q.trim()){box.classList.remove('open');return}let out=[];for(let[k,v]of Object.entries(DATA)){let d=v[LANG],score=qaSearchScore(k,d,q);if(score>0)out.push([score,k,d,p17Kind(k)])}out.sort((a,b)=>b[0]-a[0]||a[2].title.localeCompare(b[2].title));window._qaSearchResults=out;let groups=['content','tool','lab'].map(kind=>[kind,out.filter(x=>x[3]===kind).slice(0,6)]).filter(x=>x[1].length);box.innerHTML=groups.length?groups.map(([kind,rows])=>`<div class="search-group-title">${p17KindLabel(kind)}</div>${rows.map(([,k,d])=>`<div class="result" data-key="${k}" onclick="qaSearchNavigate('${k}')"><b>${topicMeta[k][0]} ${d.title}</b><br><small>${d.subtitle}</small></div>`).join('')}`).join(''):`<div class="result">${LANG==='en'?'No matching topic found.':LANG==='es'?'No se encontró un tema relacionado.':'Nenhum tópico relacionado encontrado.'}</div>`;box.classList.add('open')};
function qaSearchNavigate(k){qaNavigate(k);let q=document.getElementById('searchInput');if(q)q.value='';document.getElementById('searchResults')?.classList.remove('open')}
function p17GlossaryBox(k){let d=DATA[k]?.[LANG];if(!d)return '';let text=[d.title,d.subtitle,d.qa_tip,...d.sections.flat()].join(' ').toLowerCase(),dict=P17_GLOSSARY[LANG],found=Object.entries(dict).filter(([term])=>text.includes(term.toLowerCase())).slice(0,8);if(!found.length)return '';let title=LANG==='en'?'Terms in this topic':LANG==='es'?'Términos en este tema':'Termos neste conteúdo';let all=LANG==='en'?'Open full glossary':LANG==='es'?'Abrir glosario completo':'Abrir glossário completo';return `<section class="topic-section contextual-glossary"><span class="tag">📚 Glossário</span><h2>${title}</h2><div class="glossary-chips">${found.map(([term,desc])=>`<details class="glossary-chip"><summary>${term}</summary><p>${desc}</p></details>`).join('')}</div><button class="btn" onclick="qaNavigate('glossary')">📚 ${all}</button></section>`}
const p17RenderTopic=renderTopic;renderTopic=function(k){p17RenderTopic(k);let main=document.getElementById('main'),tip=main.querySelector('.tip'),html=p17GlossaryBox(k);if(html&&tip)tip.insertAdjacentHTML('beforebegin',html)};

function qaCpfDigits(base){let a=base.split('').map(Number),sum=a.reduce((n,x,i)=>n+x*(10-i),0),d1=(sum*10)%11;if(d1===10)d1=0;a.push(d1);sum=a.reduce((n,x,i)=>n+x*(11-i),0);let d2=(sum*10)%11;if(d2===10)d2=0;return base+String(d1)+String(d2)}
function qaCnpjDv(base){const val=c=>/[0-9]/.test(c)?+c:c.charCodeAt(0)-48;const calc=(str,w)=>{let sum=[...str].reduce((n,c,i)=>n+val(c)*w[i],0),r=sum%11;return r<2?0:11-r};let d1=calc(base,[5,4,3,2,9,8,7,6,5,4,3,2]);let d2=calc(base+d1,[6,5,4,3,2,9,8,7,6,5,4,3,2]);return base+d1+d2}
function qaRndDigits(n){return Array.from({length:n},()=>Math.floor(Math.random()*10)).join('')}
function qaRndAlphaNum(n){const c='0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ';return Array.from({length:n},()=>c[Math.floor(Math.random()*c.length)]).join('')}
function qaPick(a){return a[Math.floor(Math.random()*a.length)]}
function qaFmtCpf(v){return v.replace(/(\d{3})(\d{3})(\d{3})(\d{2})/,'$1.$2.$3-$4')}
function qaFmtCnpj(v){return v.replace(/(.{2})(.{3})(.{3})(.{4})(.{2})/,'$1.$2.$3/$4-$5')}
const QA_LOC={pt:{country:'Brasil',first:['Marina','Lucas','Ana','Rafael','Camila','Bruno','Sofia','Diego'],last:['Almeida','Silva','Oliveira','Costa','Martins','Souza'],cities:[['São Paulo','SP','01310-000'],['Campinas','SP','13010-000'],['Rio de Janeiro','RJ','20040-000'],['Curitiba','PR','80010-000'],['Belo Horizonte','MG','30110-000']],streets:['Rua Exemplo','Avenida Teste','Rua das Flores','Avenida Central'],phones:['11','19','21','31','41']},en:{country:'United States',first:['Olivia','Liam','Emma','Noah','Sophia','James','Ava','Lucas'],last:['Miller','Johnson','Brown','Davis','Wilson','Taylor'],cities:[['New York','NY','10001'],['Los Angeles','CA','90001'],['Chicago','IL','60601'],['Austin','TX','78701'],['Seattle','WA','98101']],streets:['Test Street','Example Avenue','Quality Lane','Automation Road'],areas:['212','213','312','512','206']},es:{country:'España',first:['María','Lucía','Sofía','Daniel','Pablo','Laura','Carlos','Elena'],last:['García','Martínez','López','Sánchez','Pérez','Gómez'],cities:[['Madrid','Madrid','28001'],['Barcelona','Barcelona','08001'],['Valencia','Valencia','46001'],['Sevilla','Sevilla','41001'],['Bilbao','Bizkaia','48001']],streets:['Calle Ejemplo','Avenida de Prueba','Calle Mayor','Paseo Central']}};
function qaPerson(){let l=QA_LOC[LANG];return qaPick(l.first)+' '+qaPick(l.last)}
function qaUsSsn(){return `9${String(Math.floor(Math.random()*100)).padStart(2,'0')}-${String(10+Math.floor(Math.random()*80)).padStart(2,'0')}-${String(1000+Math.floor(Math.random()*8000)).padStart(4,'0')}`}
function qaEsDni(){let n=String(Math.floor(Math.random()*99999999)).padStart(8,'0'),letters='TRWAGMYFPDXBNJZSQVHLCKE';return n+letters[Number(n)%23]}
function qaEsNie(){let p=qaPick(['X','Y','Z']),n=String(Math.floor(Math.random()*9999999)).padStart(7,'0'),letters='TRWAGMYFPDXBNJZSQVHLCKE',v=Number(({X:'0',Y:'1',Z:'2'})[p]+n);return p+n+letters[v%23]}
function qaPhone(valid=true){if(!valid)return LANG==='pt'?'+55 11 ABC':LANG==='en'?'+1 (000) 12':' +34 ABC';if(LANG==='pt'){let d=qaPick(QA_LOC.pt.phones);return `+55 (${d}) 9${qaRndDigits(4)}-${qaRndDigits(4)}`}if(LANG==='en'){let a=qaPick(QA_LOC.en.areas);return `+1 (${a}) 555-${String(100+Math.floor(Math.random()*100)).padStart(4,'0')}`}return `+34 ${qaPick(['6','7'])}${qaRndDigits(2)} ${qaRndDigits(3)} ${qaRndDigits(3)}`}
function qaAddress(valid=true){let l=QA_LOC[LANG],c=qaPick(l.cities);if(!valid)return LANG==='pt'?'Endereço/CEP propositalmente inválido':LANG==='en'?'Intentionally invalid address/ZIP Code':'Dirección/código postal intencionalmente inválido';let n=10+Math.floor(Math.random()*980);if(LANG==='pt')return `${qaPick(l.streets)}, ${n} - Bairro Exemplo - ${c[0]}/${c[1]} - CEP ${c[2]} - Brasil`;if(LANG==='en')return `${n} ${qaPick(l.streets)}, ${c[0]}, ${c[1]} ${c[2]}, United States`;return `${qaPick(l.streets)}, ${n} - ${c[0]}, ${c[1]} - Código Postal ${c[2]} - España`}
function qaTestCard(){let cards=[['Visa','4242 4242 4242 4242','123'],['Mastercard','5555 5555 5555 4444','123'],['American Express','3782 822463 10005','1234']],c=qaPick(cards),name=qaPerson(),y=new Date().getFullYear()+3,m=String(1+Math.floor(Math.random()*12)).padStart(2,'0');return `${name} | ${c[0]} | ${c[1]} | ${m}/${String(y).slice(-2)} | CVV/CVC ${c[2]} | TEST/SANDBOX`}
function qaTestDataOne(type,mode){let valid=mode!=='invalid';if(type==='person')return valid?qaPerson():'';if(type==='email'){let n=qaPerson().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replaceAll(' ','.');return valid?n+'@example.com':n+'example.com'}if(type==='phone')return qaPhone(valid);if(type==='address')return qaAddress(valid);if(type==='password')return valid?'Qa!'+qaRndAlphaNum(10):'123';if(type==='date'){let y=1980+Math.floor(Math.random()*30),m=1+Math.floor(Math.random()*12),d=1+Math.floor(Math.random()*28);return LANG==='en'?`${String(m).padStart(2,'0')}/${String(d).padStart(2,'0')}/${y}`:`${String(d).padStart(2,'0')}/${String(m).padStart(2,'0')}/${y}`}if(type==='number')return mode==='boundary'?'0 | 1 | 99 | 100 | 101':String(Math.floor(Math.random()*10000));if(type==='string')return mode==='boundary'?'"" | A | '+('X'.repeat(50))+' | '+('X'.repeat(51)):'QA-LAB-'+qaRndAlphaNum(8);if(type==='card')return qaTestCard();if(LANG==='pt'){if(type==='cpf'){let x=qaCpfDigits(qaRndDigits(9));if(!valid)x=x.slice(0,10)+((+x[10]+1)%10);return qaFmtCpf(x)}if(type==='cnpj'||type==='cnpj-alpha'){let base=type==='cnpj'?qaRndDigits(12):qaRndAlphaNum(12),x=qaCnpjDv(base);if(!valid)x=x.slice(0,13)+(x[13]==='9'?'0':'9');return qaFmtCnpj(x)}}if(LANG==='en'){if(type==='ssn')return valid?qaUsSsn():'000-00-0000';if(type==='itin')return valid?`9${qaRndDigits(2)}-${qaPick(['70','71','72','73','74','75','76','77','78','79','80','81','82','83','84','85','86','87','88'])}-${qaRndDigits(4)}`:'123-45-6789';if(type==='ein')return valid?`${qaPick(['10','12','20','27','30','35','80','81','82','83','84','85','86','87','88'])}-${qaRndDigits(7)}`:'00-0000000'}if(LANG==='es'){if(type==='dni')return valid?qaEsDni():qaRndDigits(8)+'A';if(type==='nie')return valid?qaEsNie():'A'+qaRndDigits(7)+'0'}return qaRndAlphaNum(12)}
function qaGenerateTestData(){let type=document.getElementById('tdType').value,mode=document.getElementById('tdMode').value,q=Math.min(50,Math.max(1,+document.getElementById('tdQty').value||1)),rows=Array.from({length:q},()=>qaTestDataOne(type,mode));window._qaTD=rows;document.getElementById('tdOutput').textContent=rows.join('\n')}
function qaCopyTestData(){navigator.clipboard?.writeText((window._qaTD||[]).join('\n'))}
function qaDownloadTestData(kind){let rows=window._qaTD||[];if(!rows.length)return;let body=kind==='json'?JSON.stringify(rows,null,2):'value\n'+rows.map(x=>'"'+String(x).replaceAll('"','""')+'"').join('\n');let b=new Blob([body],{type:kind==='json'?'application/json':'text/csv'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='qa-test-data.'+(kind==='json'?'json':'csv');a.click();URL.revokeObjectURL(a.href)}
function qaDataOptions(){let common={pt:[['person','👤 Pessoa'],['cpf','🪪 CPF'],['cnpj','🏢 CNPJ numérico'],['cnpj-alpha','🏢 CNPJ alfanumérico'],['email','📧 E-mail'],['phone','📱 Telefone'],['address','🏠 Endereço + CEP'],['card','💳 Cartão de teste'],['password','🔐 Senha'],['date','📅 Data'],['number','🔢 Número'],['string','📝 String']],en:[['person','👤 Person'],['ssn','🪪 SSN'],['itin','🪪 ITIN'],['ein','🏢 EIN'],['email','📧 Email'],['phone','📱 Phone'],['address','🏠 Address + ZIP Code'],['card','💳 Test card'],['password','🔐 Password'],['date','📅 Date'],['number','🔢 Number'],['string','📝 String']],es:[['person','👤 Persona'],['dni','🪪 DNI / NIF'],['nie','🪪 NIE'],['email','📧 Correo electrónico'],['phone','📱 Teléfono'],['address','🏠 Dirección + Código Postal'],['card','💳 Tarjeta de prueba'],['password','🔐 Contraseña'],['date','📅 Fecha'],['number','🔢 Número'],['string','📝 String']]};return common[LANG]}
function renderTestDataGenerator(){let x={pt:{t:'Gerador de Massa de Testes',s:'Dados sintéticos para cenários positivos, negativos e valores-limite - sem consultar pessoas reais.',type:'Tipo de dado',mode:'Modo',qty:'Quantidade',gen:'Gerar massa',copy:'Copiar tudo',warn:'Dados exclusivamente para testes. Identificadores são sintéticos; cartões usam números documentados para sandbox e não devem ser usados em produção.',m:['Válido','Inválido','Limites']},en:{t:'QA Test Data Generator',s:'Synthetic data for positive, negative and boundary scenarios - without querying real people.',type:'Data type',mode:'Mode',qty:'Quantity',gen:'Generate',copy:'Copy all',warn:'Testing data only. Identifiers are synthetic; cards use documented sandbox numbers and must not be used in production.',m:['Valid','Invalid','Boundary']},es:{t:'Generador de Datos de Prueba',s:'Datos sintéticos para escenarios positivos, negativos y límites - sin consultar personas reales.',type:'Tipo de dato',mode:'Modo',qty:'Cantidad',gen:'Generar',copy:'Copiar todo',warn:'Datos solo para pruebas. Los identificadores son sintéticos; las tarjetas usan números documentados para sandbox y no deben usarse en producción.',m:['Válido','Inválido','Límites']}}[LANG],opts=qaDataOptions().map(([v,l])=>`<option value="${v}">${l}</option>`).join('');document.getElementById('main').innerHTML=`<div class="topic-head"><div class="breadcrumbs">QA Lab Brasil › ${x.t}</div><div class="ico">🧪</div><h1>${x.t}</h1><p>${x.s}</p></div><section class="topic-section test-data-tool"><div class="td-controls"><label>${x.type}<select id="tdType">${opts}</select></label><label>${x.mode}<select id="tdMode"><option value="valid">✅ ${x.m[0]}</option><option value="invalid">❌ ${x.m[1]}</option><option value="boundary">⚠️ ${x.m[2]}</option></select></label><label>${x.qty}<input id="tdQty" type="number" min="1" max="50" value="5"></label><button class="btn primary" onclick="qaGenerateTestData()">🧪 ${x.gen}</button></div><div class="tip">⚠️ ${x.warn}</div><pre id="tdOutput" class="td-output"></pre><div class="actions"><button class="btn" onclick="qaCopyTestData()">📋 ${x.copy}</button><button class="btn" onclick="qaDownloadTestData('json')">{ } JSON</button><button class="btn" onclick="qaDownloadTestData('csv')">📊 CSV</button></div></section>`;qaGenerateTestData();window.scrollTo(0,0)}

