function p18Title(k){let d=DATA[k]?.[LANG]||DATA[k]?.pt;return d?.title||k}
function p18Local(){let base=P18_COMPARE.pt,loc=P18_COMPARE[LANG]||base;return {...base,...loc,groups:base.groups}}
function p18Render(groupIndex=0){let L=p18Local(),g=L.groups[groupIndex]||L.groups[0];let cols=g.items.filter(k=>DATA[k]);let rows=g.rows;document.getElementById('main').innerHTML=`<div class="topic-head"><div class="breadcrumbs">QA Lab Brasil › ${L.title}</div><div class="ico">⚖️</div><h1>${L.title}</h1><p>${L.sub}</p></div><section class="topic-section compare-shell"><span class="tag">⚖️ ${L.choose}</span><div class="compare-tabs">${L.groups.map((x,i)=>`<button class="btn ${i===groupIndex?'primary':''}" onclick="p18Render(${i})">${x.name}</button>`).join('')}</div><div class="compare-scroll"><table class="compare-table"><thead><tr><th>${L.criteria}</th>${cols.map(k=>`<th>${p18Title(k)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr><th>${r[0]}</th>${cols.map((k,i)=>`<td>${r[i+1]||'—'}</td>`).join('')}</tr>`).join('')}<tr><th></th>${cols.map(k=>`<td><button class="btn" onclick="qaNavigate('${k}')">${L.open} →</button></td>`).join('')}</tr></tbody></table></div><div class="tip"><b>💡 ${LANG==='en'?'How to use this comparator':LANG==='es'?'Cómo usar este comparador':'Como usar este comparador'}</b><br>${LANG==='en'?'Use the table to understand trade-offs, then open each module for installation, practical examples and official resources.':LANG==='es'?'Use la tabla para entender diferencias y después abra cada módulo para instalación, ejemplos prácticos y recursos oficiales.':'Use a tabela para entender diferenças e trade-offs; depois abra cada módulo para instalação, exemplos práticos e recursos oficiais.'}</div></section>`;window.scrollTo(0,0)}
const p18Route=route;route=function(){let h=qaRouteKey();if(h==='compare-tools'){navLabels();p18Render(0)}else p18Route()};

/* QA Lab 2.3 local test - functional search action */
function qaLabOpenBestSearchResult(){const q=document.getElementById('searchInput');if(!q||!q.value.trim())return;search(q.value);const best=(window._qaSearchResults||[])[0];if(best)qaSearchNavigate(best[1]);}
(function(){
  const q=document.getElementById('searchInput');
  const sa=document.getElementById('searchAction');
  if(sa) sa.onclick=qaLabOpenBestSearchResult;
  if(q) q.addEventListener('keydown',function(e){
    if(e.key==='Enter'){
      e.preventDefault();
      qaLabOpenBestSearchResult();
    }
  });
})();

/* QA Lab 2.3.1 - Home resets expanded navigation */
function qaBackToTopAll(){qaLabResetNavigation();const side=document.querySelector('.sidebar')||document.querySelector('#sidebar');if(side)side.scrollTo({top:0,behavior:'smooth'});window.scrollTo({top:0,behavior:'smooth'});window.setTimeout(()=>{if(typeof organizeNavigation==='function')organizeNavigation();const s2=document.querySelector('.sidebar')||document.querySelector('#sidebar');if(s2)s2.scrollTop=0},80)}
function qaLabResetNavigation(){
  // Navigation v2 uses .tree-node plus the persistent NAV_OPEN_STATE Set.
  if(typeof NAV_OPEN_STATE!=='undefined' && NAV_OPEN_STATE.clear) NAV_OPEN_STATE.clear();
  document.querySelectorAll('#navTree .tree-node.open').forEach(x=>x.classList.remove('open'));
  document.querySelectorAll('#navTree .tree-toggle').forEach(x=>{
    x.setAttribute('aria-expanded','false');
    const icon=x.querySelector('.tree-plus');
    if(icon) icon.textContent='→';
  });
  // Compatibility with older navigation markup, if present.
  document.querySelectorAll('.nav-v2.nav-group.open,.nav-v2 .nav-sub.open').forEach(x=>x.classList.remove('open'));
  document.querySelectorAll('.nav-v2 .plus').forEach(x=>x.textContent='→');
  document.querySelectorAll('.nav-v2 .group-toggle,.nav-v2 .sub-toggle').forEach(x=>x.setAttribute('aria-expanded','false'));
}
(function(){
  const home=document.querySelector('.home-link');
  if(home) home.addEventListener('click',()=>{
    qaLabResetNavigation();
    // Re-render after the hash route changes so the cleared state is preserved.
    window.setTimeout(()=>{
      if(typeof organizeNavigation==='function') organizeNavigation();
      window.scrollTo({top:0,behavior:'smooth'});
    },40);
  });
})();


/* QA Lab 2.5 - Experience & Analytics */
function qaTrackEvent(name,params={}){
  if(location.hostname!=='qualityassurancebrasil.com.br'&&location.hostname!=='www.qualityassurancebrasil.com.br')return;
  if(typeof gtag!=='function')return;
  gtag('event',name,params);
}
function qaQuickLanguage(lang){
  const btn=document.querySelector(`.language-menu .lang[data-lang="${lang}"]`);
  if(btn){btn.click();}
}
function qaEnhanceHome(){
  if(qaRouteKey())return;
  const langStat=document.querySelector('.stats .stat:nth-child(2) strong');
  if(langStat){
    langStat.innerHTML=['pt','en','es'].map(code=>`<button class="quick-lang${LANG===code?' active':''}" type="button" onclick="qaQuickLanguage('${code}')" aria-label="${code==='pt'?'Português':code==='en'?'English':'Español'}">${code.toUpperCase()}</button>`).join('<span class="quick-lang-sep"> · </span>');
  }
}
function qaGoHomeSection(id){
  const positionSection=()=>{
    const mobile=window.matchMedia('(max-width: 820px)').matches;
    /* On mobile the open navigation changes the document height. Collapse it BEFORE
       measuring the destination, otherwise the section moves after the scroll. */
    if(mobile && typeof qaLabResetNavigation==='function')qaLabResetNavigation();
    const align=()=>{
      const el=document.getElementById(id);if(!el)return;
      const header=document.querySelector('.top');
      const headerBottom=header?Math.max(0,header.getBoundingClientRect().bottom):0;
      const safety=mobile?20:16;
      const y=Math.max(0,el.getBoundingClientRect().top+window.scrollY-headerBottom-safety);
      window.scrollTo({top:y,behavior:'smooth'});
      /* Mobile browsers can reflow after the menu closes. Correct the final position
         once more so the section icon/title always remains fully visible. */
      if(mobile)window.setTimeout(()=>{
        const target=document.getElementById(id);if(!target)return;
        const sticky=document.querySelector('.top');
        const bottom=sticky?Math.max(0,sticky.getBoundingClientRect().bottom):0;
        const delta=target.getBoundingClientRect().top-bottom-20;
        if(Math.abs(delta)>4)window.scrollBy({top:delta,behavior:'smooth'});
      },260);
    };
    window.requestAnimationFrame(()=>window.requestAnimationFrame(align));
  };
  const go=()=>window.setTimeout(positionSection,100);
  if(qaRouteKey()){
    qaNavigate('');window.setTimeout(go,100);
  }else go();
}
function qaAppendAuthorNav(){
  const root=document.getElementById('navTree');if(!root||root.querySelector('.author-nav-group'))return;
  const labels={pt:{about:'Sobre o Autor',contact:'Contato'},en:{about:'About the Author',contact:'Contact'},es:{about:'Sobre el Autor',contact:'Contacto'}}[LANG];
  const wrap=document.createElement('div');wrap.className='tree-node depth-1 author-nav-group';
  wrap.innerHTML=`<div class="author-nav-row"><button class="author-main-link" type="button"><span>👤</span><span class="tree-label">${labels.about}</span></button><button class="author-nav-toggle" type="button" aria-expanded="false" aria-label="${labels.about}"><span class="tree-plus">→</span></button></div><div class="tree-children author-shortcuts"><button type="button" data-author-section="authorSection">👤 ${labels.about}</button><a href="https://www.linkedin.com/in/rodrigo-martins-ferrari-02b49449/" target="_blank" rel="noopener" data-track="linkedin_click">💼 LinkedIn ↗</a><a href="https://github.com/Rodrigoferrari1" target="_blank" rel="noopener" data-track="github_click">💻 GitHub ↗</a><button type="button" data-author-section="contactSection">✉️ ${labels.contact} →</button></div>`;
  root.appendChild(wrap);
  const toggle=wrap.querySelector('.author-nav-toggle');
  toggle.onclick=()=>{const on=wrap.classList.toggle('open');toggle.setAttribute('aria-expanded',String(on));toggle.querySelector('.tree-plus').textContent=on?'↓':'→';};
  wrap.querySelector('.author-main-link').onclick=()=>qaGoHomeSection('authorSection');
  wrap.querySelectorAll('[data-author-section]').forEach(b=>b.onclick=()=>qaGoHomeSection(b.dataset.authorSection));
}
