/* QA Lab 3.0 RC2 - UX/content corrections after full local review */
function p31Esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function p31StructuredText(text){
  if(!String(text).includes('\n')) return `<p>${text}</p>`;
  const lines=String(text).split('\n').filter(Boolean);
  return `<div class="structured-content">${lines.map((line,i)=>{
    let m=line.match(/^([^:]{2,35}):\s*(.*)$/); if(m)return `<div class="structured-row"><strong>${p31Esc(m[1])}</strong><span>${p31Esc(m[2])}</span></div>`;
    return i===0?`<h3>${p31Esc(line)}</h3>`:`<p>${p31Esc(line)}</p>`;
  }).join('')}</div>`;
}
