function ctflL(){return CTFL_I18N[LANG]||CTFL_I18N.pt}
function ctflProgress(){try{return JSON.parse(localStorage.getItem('qalab-ctfl-progress')||'{}')}catch(_){return {}}}
function ctflSave(p){localStorage.setItem('qalab-ctfl-progress',JSON.stringify(p))}
async function ctflLoad(){if(CTFL_BANK)return CTFL_BANK;const r=await fetch('/data/ctfl-questions.json?v=3.1',{cache:'no-store'});CTFL_BANK=await r.json();return CTFL_BANK}
function ctflShuffle(a){a=[...a];for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function ctflChapterName(k){let c=CTFL_BANK?.chapters?.[k];return c?c[{pt:0,en:1,es:2}[LANG]]:k}
function ctflConceptId(q){return String(q.id||'').replace(/-\d+$/,'')}
function ctflUniqueConcepts(pool){let by=new Map();ctflShuffle(pool).forEach(q=>{let k=ctflConceptId(q);if(!by.has(k))by.set(k,[]);by.get(k).push(q)});return [...by.values()]}
function ctflSelect(pool,count,usedConcepts=new Set()){let p=ctflProgress(),seen=p.seen||{};let groups=ctflUniqueConcepts(pool).filter(g=>!usedConcepts.has(ctflConceptId(g[0])));groups.sort((a,b)=>Math.min(...a.map(q=>seen[q.id]||0))-Math.min(...b.map(q=>seen[q.id]||0))||Math.random()-.5);let out=[];for(const g of groups){if(out.length>=count)break;let q=[...g].sort((a,b)=>(seen[a.id]||0)-(seen[b.id]||0)||Math.random()-.5)[0];out.push(q);usedConcepts.add(ctflConceptId(q))}return out}
function ctflSpaceConcepts(items){let remaining=[...items],out=[],last='';while(remaining.length){let idx=remaining.findIndex(q=>ctflConceptId(q)!==last);if(idx<0)idx=0;let q=remaining.splice(idx,1)[0];out.push(q);last=ctflConceptId(q)}return out}
function ctflBalancedSelect(pool,dist){let out=[],used=new Set();Object.entries(dist).forEach(([ch,n])=>{out.push(...ctflSelect(pool.filter(q=>q.chapter===ch),n,used))});if(out.length<Object.values(dist).reduce((a,b)=>a+b,0)){out.push(...ctflSelect(pool,Object.values(dist).reduce((a,b)=>a+b,0)-out.length,used))}return ctflSpaceConcepts(ctflShuffle(out))}
async function renderSimulators(){await ctflLoad();const L=ctflL(),p=ctflProgress(),seen=Object.keys(p.seen||{}).length,best=p.best||0;qaUpdateSeo('simulators');document.title=`${L.title} | QA Lab Brasil`;document.querySelector('link[rel="canonical"]')?.setAttribute('href',QA_BASE_URL+'/simulators');document.getElementById('main').innerHTML=`<div class="topic-head simulator-head"><div class="breadcrumbs">QA Lab Brasil › ${L.title}</div><div class="ico">🎓</div><h1>${L.title}</h1><p>${L.sub}</p></div><section class="topic-section sim-intro"><span class="tag">🎓 CTFL v4.0.1</span><h2>${L.ctfl}</h2><p>${L.note}</p><div class="sim-stats"><div><strong>${CTFL_BANK.count}</strong><span>${LANG==='pt'?'questões autorais':LANG==='en'?'original questions':'preguntas originales'}</span></div><div><strong>${seen}/${CTFL_BANK.count}</strong><span>${L.seen}</span></div><div><strong>${best}%</strong><span>${L.best}</span></div></div><div class="tip">ℹ️ ${L.official}</div><div class="actions"><a class="btn" href="https://www.istqb.org/certifications/certified-tester-foundation-level-ctfl-v4-0/" target="_blank" rel="noopener noreferrer">🌐 ${LANG==='pt'?'Referência oficial ISTQB':LANG==='en'?'Official ISTQB reference':'Referencia oficial ISTQB'} ↗</a></div></section><section class="sim-mode-grid"><button class="sim-mode" onclick="ctflStart('quick')"><b>⚡ ${L.quick}</b><span>${L.q10}</span></button><button class="sim-mode" onclick="ctflStart('exam')"><b>📝 ${L.exam}</b><span>${L.q40}</span></button><button class="sim-mode" onclick="ctflStart('study')"><b>📖 ${L.study}</b><span>${L.instant}</span></button><button class="sim-mode" onclick="ctflShowSubjects()"><b>🎯 ${L.subject}</b><span>${L.choose}</span></button><button class="sim-mode" onclick="ctflStart('errors')"><b>🔁 ${L.errors}</b><span>${LANG==='pt'?'Prioriza questões erradas':LANG==='en'?'Prioritizes incorrect questions':'Prioriza preguntas incorrectas'}</span></button><button class="sim-mode" onclick="ctflStart('unseen')"><b>🆕 ${L.unseen}</b><span>${LANG==='pt'?'Evita repetição recente':LANG==='en'?'Avoids recent repetition':'Evita repetición reciente'}</span></button><button class="sim-mode" onclick="ctflStart('random')"><b>🎲 ${L.random}</b><span>${L.q10}</span></button></section><div id="simSubjectPanel"></div><div class="sim-footer-actions"><button class="btn" onclick="ctflReset()">🗑️ ${L.reset}</button></div>`;window.scrollTo(0,0)}
function ctflShowSubjects(){const L=ctflL(),el=document.getElementById('simSubjectPanel');el.innerHTML=`<section class="topic-section"><h2>🎯 ${L.choose}</h2><div class="sim-subjects">${Object.keys(CTFL_BANK.chapters).map(k=>`<button class="btn" onclick="ctflStart('subject','${k}')">${ctflChapterName(k)}</button>`).join('')}</div></section>`;el.scrollIntoView({behavior:'smooth',block:'center'})}
function ctflReset(){if(!confirm(ctflL().confirmReset))return;localStorage.removeItem('qalab-ctfl-progress');renderSimulators()}
async function ctflStart(mode,subject=null){await ctflLoad();qaTrackEvent('ctfl_simulator_start',{mode:mode,subject:subject||'all',language:LANG});let pool=CTFL_BANK.questions,p=ctflProgress(),count=10;if(mode==='exam')count=40;if(mode==='subject'){pool=pool.filter(q=>q.chapter===subject);count=Math.min(20,pool.length)}if(mode==='errors'){let ids=new Set(p.errors||[]);pool=pool.filter(q=>ids.has(q.id));if(!pool.length){alert(ctflL().emptyErrors);return}count=Math.min(20,pool.length)}if(mode==='unseen'){let seen=p.seen||{};let u=pool.filter(q=>!seen[q.id]);if(u.length)pool=u;else alert(ctflL().allSeen);count=Math.min(20,pool.length)}if(mode==='random')pool=ctflShuffle(pool);let qs;if(mode==='exam')qs=ctflBalancedSelect(pool,{fundamentals:8,sdlc:6,static:4,techniques:11,management:9,tools:2});else if(['quick','study'].includes(mode))qs=ctflBalancedSelect(pool,{fundamentals:2,sdlc:2,static:1,techniques:2,management:2,tools:1});else qs=mode==='random'?ctflSelect(pool,count):ctflSelect(pool,count);qs=ctflSpaceConcepts(qs);CTFL_SESSION={mode,subject,qs,index:0,answers:{},review:new Set(),started:Date.now(),duration:mode==='exam'?3600:0};ctflRenderQuestion();if(mode==='exam')ctflStartTimer()}
function ctflStartTimer(){clearInterval(CTFL_TIMER);CTFL_TIMER=setInterval(()=>{if(!CTFL_SESSION)return clearInterval(CTFL_TIMER);let left=CTFL_SESSION.duration-Math.floor((Date.now()-CTFL_SESSION.started)/1000);let el=document.getElementById('simTimer');if(el)el.textContent=ctflFmt(Math.max(0,left));if(left<=0){clearInterval(CTFL_TIMER);ctflFinish()}},1000)}
function ctflFmt(s){return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`}
function ctflRenderQuestion(){const S=CTFL_SESSION,L=ctflL(),q=S.qs[S.index],ans=S.answers[q.id],study=S.mode==='study';document.getElementById('main').innerHTML=`<div class="topic-head sim-question-head"><div class="breadcrumbs">QA Lab Brasil › ${L.title} › CTFL</div><h1>${L.question} ${S.index+1} ${L.of} ${S.qs.length}</h1><div class="sim-progress"><span>${Object.keys(S.answers).length}/${S.qs.length} ${L.answered}</span>${S.mode==='exam'?`<strong>⏱️ <span id="simTimer">${ctflFmt(Math.max(0,S.duration-Math.floor((Date.now()-S.started)/1000)))}</span></strong>`:''}</div><div class="sim-bar"><i style="width:${((S.index+1)/S.qs.length)*100}%"></i></div></div><section class="topic-section sim-question"><span class="tag">${ctflChapterName(q.chapter)} · ${q.difficulty}</span><h2>${q.text[LANG]}</h2><div class="sim-options">${q.options[LANG].map((o,i)=>`<button class="sim-option ${ans===i?'selected':''}" onclick="ctflAnswer(${i})" ${study&&ans!==undefined?'disabled':''}><span>${String.fromCharCode(65+i)}</span><b>${o}</b></button>`).join('')}</div>${study&&ans!==undefined?ctflFeedback(q,ans):''}<label class="sim-review"><input type="checkbox" ${S.review.has(q.id)?'checked':''} onchange="ctflToggleReview(this.checked)"> ${L.mark}</label><div class="sim-nav"><button class="btn" onclick="ctflMove(-1)" ${S.index===0?'disabled':''}>← ${L.prev}</button><button class="btn" onclick="renderSimulators()">${L.home}</button>${S.index<S.qs.length-1?`<button class="btn primary" onclick="ctflMove(1)">${L.next} →</button>`:`<button class="btn primary" onclick="ctflFinish()">${L.finish} ✓</button>`}</div></section>`;requestAnimationFrame(()=>{let head=document.querySelector('.sim-question-head');if(head){let offset=window.innerWidth<=820?126:82;window.scrollTo({top:Math.max(0,head.getBoundingClientRect().top+window.scrollY-offset),behavior:'smooth'})}})}
function ctflFeedback(q,ans){const L=ctflL(),ok=ans===q.correct;return `<div class="sim-feedback ${ok?'ok':'bad'}"><b>${ok?'✅ '+L.correct:'❌ '+L.wrong}</b><p><strong>${L.explain}:</strong> ${q.explanation[LANG]}</p></div>`}
function ctflAnswer(i){let S=CTFL_SESSION,q=S.qs[S.index];S.answers[q.id]=i;if(S.mode==='study')ctflRenderQuestion();else document.querySelectorAll('.sim-option').forEach((b,n)=>b.classList.toggle('selected',n===i))}
function ctflToggleReview(on){let q=CTFL_SESSION.qs[CTFL_SESSION.index];on?CTFL_SESSION.review.add(q.id):CTFL_SESSION.review.delete(q.id)}
function ctflMove(d){CTFL_SESSION.index=Math.max(0,Math.min(CTFL_SESSION.qs.length-1,CTFL_SESSION.index+d));ctflRenderQuestion()}
function ctflFinish(){clearInterval(CTFL_TIMER);let S=CTFL_SESSION;if(!S)return;const L=ctflL(),elapsed=Math.floor((Date.now()-S.started)/1000);let correct=0,by={};let p=ctflProgress();p.seen=p.seen||{};p.errors=p.errors||[];let err=new Set(p.errors);S.qs.forEach(q=>{let a=S.answers[q.id],ok=a===q.correct;if(ok)correct++;by[q.chapter]=by[q.chapter]||[0,0];by[q.chapter][1]++;if(ok)by[q.chapter][0]++;p.seen[q.id]=Date.now();if(ok)err.delete(q.id);else err.add(q.id)});p.errors=[...err];let pct=Math.round(correct/S.qs.length*100);p.best=Math.max(p.best||0,pct);p.last={score:pct,date:Date.now(),count:S.qs.length};ctflSave(p);qaTrackEvent('ctfl_simulator_finish',{mode:S.mode,score:pct,questions:S.qs.length,language:LANG});let pass=pct>=65;document.getElementById('main').innerHTML=`<div class="topic-head"><div class="breadcrumbs">QA Lab Brasil › ${L.title} › ${L.result}</div><div class="ico">🎓</div><h1>${L.result}</h1><p>${L.score}: <strong>${correct}/${S.qs.length} · ${pct}%</strong> · ${L.time}: ${ctflFmt(elapsed)}</p></div><section class="topic-section sim-result"><div class="sim-score ${pass?'pass':'retry'}"><strong>${pct}%</strong><span>${pass?'✅ '+L.passed:'📚 '+L.notpassed}</span></div><h2>${L.performance}</h2><div class="sim-performance">${Object.entries(by).map(([k,v])=>`<div><span>${ctflChapterName(k)}</span><b>${v[0]}/${v[1]} · ${Math.round(v[0]/v[1]*100)}%</b><i><em style="width:${v[0]/v[1]*100}%"></em></i></div>`).join('')}</div><div class="tip">${L.note}</div><div class="actions"><button class="btn primary" onclick="renderSimulators()">🎓 ${L.again}</button><button class="btn" onclick="qaNavigate('testing')">📚 ${LANG==='pt'?'Estudar no QA Lab':LANG==='en'?'Study in QA Lab':'Estudiar en QA Lab'}</button></div></section>`;CTFL_SESSION=null;window.scrollTo(0,0)}

/* QA Lab 3.1 mobile: global search/utilities before navigation, desktop DOM restored unchanged. */
function qaArrangeResponsiveHeader(){
 const top=document.querySelector('.top'),side=document.querySelector('.side'),content=document.querySelector('.content'),brand=side?.querySelector('.brand');
 if(!top||!side||!content)return;
 if(window.matchMedia('(max-width: 820px)').matches){
   if(top.parentElement!==side){brand?.insertAdjacentElement('afterend',top)}
 }else if(top.parentElement!==content){content.insertBefore(top,content.firstChild)}
}
qaArrangeResponsiveHeader();
window.addEventListener('resize',qaArrangeResponsiveHeader,{passive:true});


