let QA_PDF_CATALOG=null;
const QA_PDF_GROUPS={
 testing:['testing','debug-accessibility','mobile','performance','security'],
 tools:['tech','programming','tools','git'],
 api:['api'], automation:['automation'], devops:['devops','cloud','observability'],
 methodology:['methodology'], engineering:['engineering','architecture'], management:['management','work'],
 data:['data'], future:['future'], learn:['learn']
};
function qaPdfText(){return {
 pt:{title:'Central de PDFs',sub:'Encontre e baixe rapidamente os materiais do QA Lab Brasil.',search:'Pesquisar PDF',all:'Todos',guide:'Guia do tópico',install:'Instalação e Configuração',close:'Fechar',empty:'Nenhum PDF encontrado.',cats:{testing:'QA & Testes',tools:'Ferramentas',api:'API',automation:'Automação',devops:'DevOps & Infraestrutura',methodology:'Metodologias',engineering:'Engenharia de Software',management:'Gestão de QA',data:'Dados & Banco de Dados',future:'IA & Futuro',learn:'Fundamentos'}},
 en:{title:'PDF Center',sub:'Quickly find and download QA Lab Brasil materials.',search:'Search PDFs',all:'All',guide:'Topic guide',install:'Installation & Setup',close:'Close',empty:'No PDF found.',cats:{testing:'QA & Testing',tools:'Tools',api:'API',automation:'Automation',devops:'DevOps & Infrastructure',methodology:'Methodologies',engineering:'Software Engineering',management:'QA Management',data:'Data & Databases',future:'AI & Future',learn:'Fundamentals'}},
 es:{title:'Central de PDFs',sub:'Encuentre y descargue rápidamente los materiales de QA Lab Brasil.',search:'Buscar PDF',all:'Todos',guide:'Guía del tema',install:'Instalación y Configuración',close:'Cerrar',empty:'No se encontró ningún PDF.',cats:{testing:'QA & Pruebas',tools:'Herramientas',api:'API',automation:'Automatización',devops:'DevOps e Infraestructura',methodology:'Metodologías',engineering:'Ingeniería de Software',management:'Gestión de QA',data:'Datos y Bases de Datos',future:'IA y Futuro',learn:'Fundamentos'}}
 }[LANG]}
function qaPdfCategory(group){for(const [cat,groups] of Object.entries(QA_PDF_GROUPS))if(groups.includes(group))return cat;return 'tools'}
async function qaOpenPdfHub(){
 if(!QA_PDF_CATALOG){try{QA_PDF_CATALOG=await fetch('/data/pdf-catalog.json?v=3.1.1',{cache:'no-store'}).then(r=>r.json())}catch(_){QA_PDF_CATALOG=[]}}
 document.getElementById('qaPdfHub')?.remove(); const L=qaPdfText();
 const wrap=document.createElement('div');wrap.id='qaPdfHub';wrap.className='pdf-hub-overlay';wrap.innerHTML=`<section class="pdf-hub" role="dialog" aria-modal="true" aria-label="${L.title}"><div class="pdf-hub-head"><div><span class="tag">📄 QA Lab Brasil</span><h2>${L.title}</h2><p>${L.sub}</p></div><button class="pdf-hub-close" type="button" onclick="qaClosePdfHub()" aria-label="${L.close}">×</button></div><div class="pdf-hub-search">🔎 <input id="pdfHubSearch" type="search" placeholder="${L.search}" oninput="qaRenderPdfHub()"></div><div id="pdfHubCats" class="pdf-hub-cats"></div><div id="pdfHubList" class="pdf-hub-list"></div></section>`;
 wrap.addEventListener('click',e=>{if(e.target===wrap)qaClosePdfHub()});document.body.appendChild(wrap);window.QA_PDF_ACTIVE='all';qaRenderPdfHub();setTimeout(()=>document.getElementById('pdfHubSearch')?.focus(),50)
}
function qaClosePdfHub(){document.getElementById('qaPdfHub')?.remove()}
function qaPdfSetCat(cat){window.QA_PDF_ACTIVE=cat;qaRenderPdfHub()}
function qaPdfNorm(v){return String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase()}
function qaRenderPdfHub(){const L=qaPdfText(),q=qaPdfNorm(document.getElementById('pdfHubSearch')?.value||''),active=window.QA_PDF_ACTIVE||'all';let rows=(QA_PDF_CATALOG||[]).map(x=>({...x,cat:qaPdfCategory(x.group),title:DATA[x.key]?.[LANG]?.title||x.key}));if(q)rows=rows.filter(x=>qaPdfNorm(x.title+' '+x.key).includes(q));if(!q&&active!=='all')rows=rows.filter(x=>x.cat===active);const counts={};(QA_PDF_CATALOG||[]).forEach(x=>{let c=qaPdfCategory(x.group);counts[c]=(counts[c]||0)+1});let visualActive=q?'all':active;let cats=`<button class="pdf-cat ${visualActive==='all'?'on':''}" onclick="qaPdfSetCat('all')">${L.all}</button>`+Object.keys(L.cats).filter(c=>counts[c]).map(c=>`<button class="pdf-cat ${visualActive===c?'on':''}" onclick="qaPdfSetCat('${c}')">${L.cats[c]}</button>`).join('');document.getElementById('pdfHubCats').innerHTML=cats;document.getElementById('pdfHubList').innerHTML=rows.length?rows.sort((a,b)=>a.title.localeCompare(b.title,LANG)).map(x=>`<article class="pdf-item"><div><span>${topicMeta[x.key]?.[0]||'📄'}</span><b>${x.title}</b><small>${L.cats[x.cat]||''}</small></div><div class="pdf-item-actions">${x.guide?`<a class="btn primary" href="/pdf/${LANG}/${x.key}.pdf" download>📘 ${L.guide}</a>`:''}${x.install?`<a class="btn" href="/pdf/${LANG}/${x.key}-installation.pdf" download>🛠️ ${L.install}</a>`:''}</div></article>`).join(''):`<div class="pdf-empty">${L.empty}</div>`}
document.addEventListener('keydown',e=>{if(e.key==='Escape')qaClosePdfHub()});

/* QA Lab 3.1.1 - mobile destination focus for header utilities and search */
function qaMobileFocusDestination(){
  if(!window.matchMedia('(max-width: 820px)').matches)return;
  requestAnimationFrame(()=>requestAnimationFrame(()=>{
    const main=document.getElementById('main');
    if(!main)return;
    const top=document.querySelector('.top');
    const offset=(top?.getBoundingClientRect().height||0)+10;
    const y=Math.max(0,window.scrollY+main.getBoundingClientRect().top-offset);
    window.scrollTo({top:y,behavior:'smooth'});
  }));
}
const qaNavigateBeforeMobileUX=qaNavigate;
qaNavigate=function(key){
  qaNavigateBeforeMobileUX(key);
  if(key==='test-data-generator'||key==='simulators')qaMobileFocusDestination();
};
qaSearchNavigate=function(k){
  qaNavigateBeforeMobileUX(k);
  let q=document.getElementById('searchInput');if(q)q.value='';
  document.getElementById('searchResults')?.classList.remove('open');
  qaMobileFocusDestination();
};

/* QA Lab Brasil 3.1.2 - Simulator UX (clean production baseline) */
function qaSimRunnerCleanup(){
  document.body.classList.remove('qa-sim-active');
  clearInterval(CTFL_TIMER);
}
function qaSimAlignNav(){
  if(!document.body.classList.contains('qa-sim-active')||window.innerWidth<=820)return;
  const card=document.querySelector('.sim-question');
  const nav=document.querySelector('.sim-nav');
  if(!card||!nav)return;
  const r=card.getBoundingClientRect();
  nav.style.setProperty('left',`${Math.round(r.left)}px`,'important');
  nav.style.setProperty('width',`${Math.round(r.width)}px`,'important');
  nav.style.setProperty('right','auto','important');
}
const qaRouteBeforeSimUX=route;
route=function(){
  qaSimRunnerCleanup();
  qaRouteBeforeSimUX();
};
const qaRenderSimulatorsBeforeUX=renderSimulators;
renderSimulators=async function(){
  qaSimRunnerCleanup();
  return qaRenderSimulatorsBeforeUX();
};
const qaCtflRenderQuestionBeforeUX=ctflRenderQuestion;
ctflRenderQuestion=function(){
  document.body.classList.add('qa-sim-active');
  qaCtflRenderQuestionBeforeUX();
  requestAnimationFrame(()=>requestAnimationFrame(()=>{
    qaSimAlignNav();
    if(window.innerWidth<=820){
      const card=document.querySelector('.sim-question');
      if(card){
        const y=Math.max(0,window.scrollY+card.getBoundingClientRect().top-8);
        window.scrollTo({top:y,behavior:'smooth'});
      }
    }
  }));
};
const qaCtflFinishBeforeUX=ctflFinish;
ctflFinish=function(){
  qaSimRunnerCleanup();
  return qaCtflFinishBeforeUX();
};
window.addEventListener('resize',()=>requestAnimationFrame(qaSimAlignNav));

/* QA Lab Brasil 3.1.3 - mobile/tablet search placement */
function qaPositionMobileSearchResults(){
  const box=document.getElementById('searchResults');
  const search=document.querySelector('.top .search');
  if(!box||!search)return;
  if(window.innerWidth>820){
    box.classList.remove('qa-mobile-search-results');
    box.style.removeProperty('top');
    box.style.removeProperty('left');
    box.style.removeProperty('width');
    box.style.removeProperty('--qa-search-top');
    return;
  }
  const r=search.getBoundingClientRect();
  const top=Math.max(8,Math.round(r.bottom+8));
  box.classList.add('qa-mobile-search-results');
  box.style.setProperty('top',`${top}px`,'important');
  box.style.setProperty('left',`${Math.round(r.left)}px`,'important');
  box.style.setProperty('width',`${Math.round(r.width)}px`,'important');
  box.style.setProperty('--qa-search-top',`${top}px`);
}
const qaSearchBefore313=search;
search=function(q){
  qaSearchBefore313(q);
  if(document.getElementById('searchResults')?.classList.contains('open')){
    requestAnimationFrame(qaPositionMobileSearchResults);
  }
};
window.addEventListener('resize',qaPositionMobileSearchResults);
window.addEventListener('orientationchange',()=>setTimeout(qaPositionMobileSearchResults,80));
